-- 건강기능식품 축약본: 시나리오·페르소나 성분 + 자주 먹는 영양제 (100개)
-- 원본: 건강기능식품_전체_1-46101.csv(제품) · database/health_food_ingredient.csv.gz(원재료)
-- 구조는 database/health_food.sql과 같고 테이블 이름 앞에 new_. staging 단계 없이 바로 넣는다.
-- Supabase SQL Editor에 전체를 붙여넣고 Run. 다시 실행하면 new_health_food·new_health_food_ingredient만 지우고 새로 만든다.
-- 원재료 2232행

begin;

drop table if exists public.new_health_food_ingredient;
drop table if exists public.new_health_food;

create table public.new_health_food (
  report_no          text primary key,          -- 신고번호
  list_no            integer,                   -- 번호
  name               text not null,             -- 제품명
  list_name          text,                      -- 목록_제품명
  company            text,                      -- 제조사명
  list_functionality text,                      -- 목록_기능성
  registered_at      date,                      -- 등록일자
  shelf_life         text,                      -- 유통기한
  appearance         text,                      -- 성상
  intake_method      text,                      -- 섭취량/섭취방법
  packaging          text,                      -- 포장재질(방법)
  functionality      text,                      -- 기능성 내용
  storage            text,                      -- 보존 및 유통기준
  precautions        text,                      -- 섭취 시 주의사항
  ingredient_count   integer,
  pick_category      text,                      -- 축약본 범주 (원본에 없는 열)
  pick_reason        text                       -- 축약본에 넣은 이유 (원본에 없는 열)
);

-- 원재료 테이블 (제품 1 : N 원재료)
create table public.new_health_food_ingredient (
  id              bigint generated always as identity primary key,
  report_no       text not null references public.new_health_food(report_no) on delete cascade,
  ingredient_type text not null check (ingredient_type in ('functional','other','capsule')),
                  -- functional=기능성 원재료명, other=기타 원재료명, capsule=캡슐 원재료명
  seq             integer not null,             -- 원본 목록 내 순서
  ingredient_name text not null
);

insert into public.new_health_food
  (report_no, list_no, name, list_name, company, list_functionality, registered_at, shelf_life,
   appearance, intake_method, packaging, functionality, storage, precautions, ingredient_count,
   pick_category, pick_reason) values
  ('200400200142074', 40297, '광동 칼슘', '광동 칼슘', '광동헬스바이오(주) 2공장', null, '2025-12-16'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없으며 점박이가 있는 흰색의 장방형 제피정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장- 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[칼슘](1) 뼈와 치아 형성에 필요(2) 신경과 근육 기능 유지에 필요(3) 정상적인 혈액응고에 필요(4) 골다공증발생 위험 감소에 도움을 줌', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', null, 9, '칼슘', '시나리오: S2~S8 칼슘'),
  ('200400200061932', 30053, '뉴오리진 어골칼슘&비타민D', '뉴오리진 어골칼슘&비타민D', '(주)서흥', null, '2024-03-12'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없으며 점박이가 있는 흰 노랑 또는 회황색의 장방형 제피정제', '1일 1회, 1회 2정 또는 1일 2회, 1회 1정을 물과 함께 섭취하십시오.', '폴리염화비닐(PVC), 폴리염화비닐리덴(PVDC), 알루미늄호일(Al-Foil), 폴리프로필렌(PP), 폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), 고밀도폴리에틸렌(HDPE)', '칼슘 : (1) 뼈와 치아 형성에 필요 (2) 신경과 근육 기능 유지에 필요 (3) 정상적인 혈액응고에 필요 (4) 골다공증발생 위험 감소에 도움을 줌아연 : (1) 정상적인 면역기능에 필요 (2) 정상적인 세포분열에 필요비타민D : (1) 칼슘과 인이 흡수되고 이용되는데 필요 (2) 뼈의 형성과 유지에 필요 (3) 골다공증발생 위험 감소에 도움을 줌', '(1) 제품은 직사광선을 피하고 실온에서 보관 유통하십시오. (2) 제품 개봉 후에는 흡습되지 않게 밀봉하여 보관하십시오.', '(1) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 8, '칼슘', '시나리오: S2~S8 칼슘'),
  ('200400200201626', 46060, '동국 프로칼슘 치아건강', '동국 프로칼슘 치아건강', '엠에스바이오텍(주)', null, '2026-10-26'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 점박이가 있는 하양색의 장방형 츄어블 정제', '1일 1회, 1회 1정을 씹어서 섭취하십시오.', '폴리에틸렌(PE), 폴리프로필렌(PP), 폴리에틸렌테레프탈레이트(PET), 폴리스티렌(PS), 알루미늄호일(AL-Foil), 폴리염화비닐리덴(PVDC), 폴리염화비닐(PVC)', '* 비타민C①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요* 비타민D①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌* 셀레늄(또는 셀렌)①유해산소로부터 세포를 보호하는데 필요* 아연①정상적인 면역기능에 필요②정상적인 세포분열에 필요* 칼슘① 뼈와 치아 형성에 필요② 신경과 근육 기능 유지에 필요③ 정상적인 혈액응고에 필요④ 골다공증발생 위험 감소에 도움을 줌* 프로폴리스추출물① 구강에서의 항균작용에 도움을 줄 수 있음', '습기가 적고 직사광선을 피하여 서늘한 곳에 보관하며, 어린이 손에 닿지 않도록 주의하십시오.', '* 비타민 C① 과량 섭취하지 않도록 주의할 것② 신장질환이 있는 경우 섭취 전 전문가와 상담할 것③ 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것* 비타민 D①고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것②이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것* 프로폴리스추출물① 프로폴리스에 알레르기를 나타내는 사람은 섭취에 주의② 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것,* 비타민 C① 과량 섭취하지 않도록 주의할 것② 신장질환이 있는 경우 섭취 전 전문가와 상담할 것③ 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것* 비타민 D①고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것②이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것* 프로폴리스추출물① 프로폴리스에 알레르기를 나타내는 사람은 섭취에 주의② 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 17, '칼슘', '시나리오: S2~S8 칼슘'),
