  ('200400200083146', 36119, '여에스더 칼슘 마그네슘D', '여에스더 칼슘 마그네슘D', '주식회사 노바렉스', null, '2025-04-17'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미∙이취가 없는 점박이를 포함한 흰색의 흰색 장방형 제피 정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '폴리에틸렌테레프탈레이트(PET), 폴리에틸렌(PE), 고밀도폴리에틸렌(HDPE), 저밀도폴리에틸렌(LDPE), 폴리프로필렌(PP), 폴리스틸렌(PS), 폴리염화비닐리덴(PVDC), 폴리염화비닐/알루미늄호일, 알루미늄(AL)', '[칼슘] 뼈와 치아 형성에 필요, 신경과 근육 기능 유지에 필요, 정상적인 혈액응고에 필요, 골다공증발생 위험 감소에 도움을 줌[마그네슘] 에너지 이용에 필요, 신경과 근육 기능 유지에 필요[아연] 정상적인 면역기능에 필요, 정상적인 세포분열에 필요[비타민 D] 칼슘과 인이 흡수되고 이용되는데 필요, 뼈의 형성과 유지에 필요, 골다공증발생 위험 감소에 도움을 줌[망간] 뼈 형성에 필요, 에너지 이용에 필요, 유해산소로부터 세포를 보호하는데 필요[비타민 K] 정상적인 혈액응고에 필요, 뼈의 구성에 필요', '1. 고온다습한 곳과 직사광선을 피하여 습기가 적고 건조한 곳에 보관하십시오. 2. 개봉 후에는 공기의 노출을 최대한 차단하여 보관하십시오. 3. 영유아 및 어린이의 손에 닿지 않는 곳에 보관하십시오.', '특정질환, 특이체질, 알레르기체질, 임산부의 경우에는 간혹 개인에 따라 과민반응이 나타날 수 있으므로 원료를 확인하시고, 섭취전에 전문가와 상담하시기 바랍니다.제품 개봉 또는 섭취 시 포장재에 의해 다칠 우려가 있으니 주의하시기 바랍니다.이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 D] 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것[비타민 K] 항응고제 등 복용 시 전문가와 상담할 것', 17, '칼슘', '시나리오: S2~S8 칼슘'),
  ('200400200062119', 39286, '유한K2칼슘', '유한K2칼슘', '(주)서흥', null, '2025-10-21'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 하얀색의 타원형 제피정제', '1일 1회, 1회 2정을 충분한 물과 함께 섭취하십시오.', '폴리에틸렌(PE), 폴리프로필렌(PP), 고밀도폴리에틸렌(HDPE), 저밀도폴리에틸렌(LDPE), 폴리에틸렌테레프탈레이트(PET), 폴리스티렌(PS), 폴리시클로헥산-1,4-디메틸렌테레프탈레이트(PCT), 폴리염화비닐(PVC), 폴리염화비닐리덴(PVDC), 알루미늄호일(Al-Foil)', '칼슘 : (1) 뼈와 치아 형성에 필요 (2) 신경과 근육 기능 유지에 필요 (3) 정상적인 혈액응고에 필요 (4) 골다공증 발생 위험 감소에 도움을 줌비타민K : (1) 정상적인 혈액응고에 필요 (2) 뼈의 구성에 필요', '(1) 제품은 직사광선을 피하고 실온에서 보관 유통하십시오.(2) 제품 개봉 후에는 흡습되지 않게 밀봉하여 보관하십시오.', '(1) 항응고제 등 복용 시 전문가와 상담할 것(2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 10, '칼슘', '시나리오: S2~S8 칼슘'),
  ('20040017106227', 2897, '일동해조칼슘골드', '일동해조칼슘골드', '에스케이내추럴팜(주)', null, '2013-06-11'::date, '제조일로부터 24개월', '미백색의 장방형 정제로 이미, 이취가 없어야 함', '1일 2회, 1회 1정을 충분한 물과 함께 섭취하십시오.', 'PE(폴리에틸렌)병, PET(폴리에틸렌테레프탈레이트)', '[칼슘]①뼈와 치아 형성에 필요②신경과 근육 기능 유지에 필요③정상적인 혈액응고에 필요④청년기 이전에 적절한 운동과 건강한 식습관을 유지하면서 충분한 칼슘을 섭취하면 향후 골다공증발생의 위험을 감소시킬 수 있음
[비타민D]①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요', '습기가 적고 직사광선이 들지 않는 서늘한 곳에 보관하십시오.', '1) 특정 또는 특이체질이신 경우 성분 확인 후 섭취하십시오.
2) 이상증상이 생길 경우 즉시 섭취를 중단하시고 의사와 상담하십시오.
3) 섭취량 및 섭취방법을 확인한 후 섭취하여 주십시오.
4) 동봉된 방습제를 섭취하지 않도록 주의하십시오.', 20, '칼슘', '시나리오: S2~S8 칼슘'),
  ('200400170211118', 17073, '일양 칼슘 마그네슘 앤 비타민D 아연', '일양 칼슘 마그네슘 앤 비타민D 아연', '(주)비오팜', null, '2021-06-21'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 갈색과 밝은 회색의 점박이가 있는 연한회색 장방형 제피정제', '1일 1회, 1회 2정을 물과 함께 섭취하십시오.', 'PE, PP, PET, PS, PVC+AL-Foil, PVDC+AL-Foil', '[비타민D] ①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌[마그네슘] ①에너지 이용에 필요②신경과 근육 기능 유지에 필요[아연] ①정상적인 면역기능에 필요②정상적인 세포분열에 필요[칼슘] ①뼈와 치아 형성에 필요②신경과 근육 기능 유지에 필요③정상적인 혈액응고에 필요④골다공증발생 위험 감소에 도움을 줌', '실온/ ①제품은 직사광선 및 고온 다습한 곳을 피하여 서늘한 곳에 보관 유통하여야 한다.②제품은 유통 중 인습되지 않도록 포장의 파손에 주의하여야 한다.③어린이의 손이 닿지 않는 곳에 보관하십시오.', '- 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것- 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것- 알레르기 체질이신 경우 원료 성분을 확인 하신 후 섭취하십시오- 질병이나 약물을 투여하시는 분은 의사와 상의하시고, 어린이 손이 닿지 않는 곳에 보관하십시오 - 제품 개봉 또는 섭취 시 포장재에 의해 상처를 입을 수 있으니 주의하십시오', 16, '칼슘', '시나리오: S2~S8 칼슘'),
  ('20150002152134', 44709, '정관장 아이칼슘', '정관장 아이칼슘', '(주)한국인삼공사', null, '2026-08-07'::date, '제조일로부터 2년', '고유의 향미가 있고 이미, 이취가 없는 탁한 연노랑색의 액상', '1일 1회 1포를 섭취하십시오.', '폴리에틸렌(PE)', '[칼슘](1) 뼈와 치아 형성에 필요(2) 신경과 근육 기능 유지에 필요(3) 정상적인 혈액응고에 필요(4) 골다공증발생 위험 감소에 도움을 줌[마그네슘](1) 에너지 이용에 필요(2) 신경과 근육 기능 유지에 필요', '직사광선을 피하여 실온에 보관하시고 개봉 후에는 변질될 수 있으므로 바로 섭취하십시오.', ',', 13, '칼슘', '시나리오: S2~S8 칼슘'),
  ('20240028080342', 39031, '종근당건강칼슘마그네슘', '종근당건강칼슘마그네슘', '콜마비앤에이치(주)세종3공장', null, '2025-09-30'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 흰색의 장방형 제피정제', '1일 2회, 1회 1정을 물과 함께 섭취하십시오.', '병 - 폴리에틸렌(PE) 또는 폴리프로필렌(PP) 또는 폴리에틸렌테레프탈레이트(PET) PTP- 폴리염화비닐(PVC), 알루미늄호일(Al-Foil)', '1) 칼슘 - 뼈와 치아 형성에 필요, 신경과 근육 기능 유지에 필요, 정상적인 혈액응고에 필요, 골다공증발생 위험 감소에 도움을 줌2) 마그네슘- 에너지 이용에 필요, 신경과 근육 기능 유지에 필요 3) 망간 - 뼈 형성에 필요, 에너지 이용에 필요, 유해산소로부터 세포를 보호하는데 필요,4) 비타민D- 칼슘과 인이 흡수되고 이용되는데 필요, 뼈의 형성과 유지에 필요, 골다공증 발생 위험감소에 도움을 줌', '습기가 적고 직사광선을 받지 않는 실온에 보관하십시오.', '- 특이체질, 알레르기 체질의 경우에는 간혹 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인한 후 섭취 하십시오.- 용기 안의 방습제는 섭취하지 마십시오.- 고칼슘혈증이 있거나 의약품 복용 시 전문가와상담할 것- 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 16, '칼슘', '시나리오: S2~S8 칼슘'),
