  ('200400200061523', 13191, '뉴오리진 철분&엽산', '뉴오리진 철분&엽산', '(주)서흥', null, '2020-06-29'::date, '제조일부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 탁한 황갈색 또는 연한 갈색의 장방형 제피정제', '1일 1회, 1회 1정(0.85g)을 충분한 물과 함께 섭취하십시오.', '폴리염화비닐(PVC), 알루미늄호일(Al-foil), 폴리프로필렌(PP), 폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), 고밀도폴리에틸렌(HDPE), 폴리염화비닐리덴(PVDC) 등', '철 : ①체내 산소운반과 혈액생성에 필요②에너지 생성에 필요엽산 : ①세포와 혈액생성에 필요②태아 신경관의 정상 발달에 필요③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요', '① 제품은 직사광선을 피하고, 실온에서 보관 유통하십시오. ② 제품 개봉 후에는 흡습되지 않게 밀봉하여 보관하십시오.', '특히 6세 이하는 과량섭취하지 않도록 주의개봉 또는 섭취시 포장재에 의해 상처를 입을 수 있으니 주의하시기 바랍니다.', 22, '철분', '시나리오: S4 철분, S7 철분제'),
