  ('20040017017988', 6830, '듀오락 맘스 철분&엽산 플러스', '듀오락 맘스 철분&엽산 플러스', '(주)쎌바이오텍', null, '2017-05-30'::date, '제조일로부터 24개월', '이미, 이취가 없고 고유의 향미가 있는 노란 회색의 분말을 함유한 백색 경질캡슐', '1일 1회, 1회 1캡슐(500mg)을 물과 함께 섭취한다.', '내포장재질-폴리에틸렌(PE)', '①체내 산소운반과 혈액생성에 필요②에너지 생성에 필요①세포와 혈액생성에 필요②태아 신경관의 정상 발달에 필요③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①정상적인 엽산 대사에 필요①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요①뼈 형성에 필요②에너지 이용에 필요③유해산소로부터 세포를 보호하는데 필요①정상적인 면역기능에 필요②정상적인 세포분열에 필요', '습기, 일광을 피하여 서늘한 곳에 보관, 유통하십시오.', '1. 특히 6세 이하는 과량섭취하지 않도록 주의2. 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것3. 질병치료중이신 분, 알레르기, 특이체질이신 분은 의사, 약사 등 전문가와 상담 후 섭취하십시오.', 11, '철분', '시나리오: S4 철분, S7 철분제'),
