  ('20040017062206', 38273, '일양철분35mg정', '일양철분35mg정', '(주)에스엘에스', null, '2025-08-22'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미·이취가 없으며 흰색 점박이가 있는 회갈색의 장방형 코팅 정제', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', '폴리염화비닐(PVC), 알루미늄호일, 폴리에틸렌(PE), 폴리프로필렌(PP), 폴리에틸렌테레프탈레이트(PET)', '[철] 체내 산소운반과 혈액생성에 필요, 에너지 생성에 필요', '실온 / 직사광선 및 고온다습한 곳을 피해 서늘한 실온에 보관하십시오.', '1. 특정질환, 특이체질, 알레르기 체질인 경우 간혹 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인 후 섭취하십시오.2. 특히 6세 이하는 과량섭취하지 않도록 주의하십시오.3. 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.4. 제품 개봉 또는 섭취 시 포장재에 의해 상처를 입을 수 있으니 주의하십시오.', 7, '철분', '시나리오: S4 철분, S7 철분제'),
