  ('20110017019179', 37021, '일동 하이퍼 비타민C 3000', '일동 하이퍼 비타민C 3000', '주식회사 아람', null, '2025-06-16'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 흰색의 분말', '1일 1회, 1회 1포를 물과 함께 섭취하십시오.', '폴리에틸렌(PE)', '(1) 결합조직 형성과 기능유지에 필요(2) 철의 흡수에 필요(3) 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '직사광선 및 고온다습한 곳을 피하고 서늘한 곳에 보관한다. 어린이의 손에 닿지 않는 곳에 보관하십시오', ',', 1, '비타민C', '시나리오: S3 비타민C'),
  ('20040017068122', 2243, '일양비타민C1000', '일양비타민C1000', '일양약품(주)', null, '2012-05-30'::date, '제조일로부터 2년', '고유의 향미가 있고 이미·이취가 없는 밝은 백색의 장방형 정제', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', 'PTP포장재질[폴리염화비닐(PVC), 알루미늄호일]', '[비타민C] ①결합조직 형성과 기능유지에 필요 ②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '1. 직사광선을 받지 아니하며 습기가 없는 실온에 어린이 손이 닿지 않게 보관하십시오. 2. 정제상태로 공기 중에 방치하거나 제품을 다른 용기에 보관하지 마십시오.', ') 특정질환, 특이체질, 알레르기 체질인 경우 간혹 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인한 후 섭취하십시오.2) 포장재에 의해 상처를 입을 수 있으니 개봉 시 주의하십시오.3) 본 제품은 습기가 많은 곳이나, 열, 햇빛 등에 노출되면 변색 변질되므로 알루미늄 봉지 개봉 후에는 가능한 빨리 섭취하시기 바랍니다.4) 과량 섭취하지 않도록 주의하십시오.5) 신장질환이 있는 경우 섭취 전 전문가와 상담하십시오.6) 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.7) 공복에 섭취 시 위장장애를 유발할 수 있으니 식후에 섭취하십시오.8) 알루미늄 봉지 안의 습기제거제는 드시지 마십시오.', 4, '비타민C', '시나리오: S3 비타민C'),
  ('2012001700218', 2801, '종근당 비타민C 1000mg', '종근당 비타민C 1000mg', '이앤에스(주)', null, '2013-04-17'::date, '24개월', '백색의 장방형 정제', '1일 1회, 1회 1정을 물과함깨 섭취하십시오.', 'PTP포장재질[염화비닐수지(PVC), 알루미늄호일]', '[비타민C]①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '고온, 직사광선, 습기를 피해 서늘하고 통풍이 잘 되는 곳에 보관하십시오.', '(1) 유통기한을 확인하시기 바라며, 권장섭취량 및 섭취방법을 준수하시기 바랍니다.(2) 특정질환, 특이체질, 알레르기 체질인 경우 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인후 섭취하십시오.(3) 어린이가 섭취할때는 보호자의 관리 감독하에 주의하여 섭취시켜 주십시오.', 5, '비타민C', '시나리오: S3 비타민C'),
  ('200400150831706', 21068, '한미양행 비타민CDE 트리플UP', '한미양행 비타민CDE 트리플UP', '주식회사한미양행', null, '2022-06-09'::date, '제조일로부터 24개월까지', '고유의 향미를 지니고 이미, 이취가 없는 하얀색 또는 노란 하얀색 타원형 정제.', '1일 1회, 1회 1정을 충분한 물과 함께 섭취.', 'PE, PS, PET', '①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '고온다습한 곳이나 직사광선을 피하여 서늘한 곳에 보관.', '(가) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(나) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 26, '비타민C', '시나리오: S3 비타민C'),
  ('200400170061218', 17042, '고려은단 식물성 오메가3', '고려은단 식물성 오메가3', '(주)알피바이오', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2021-06-17'::date, '제조일로부터 36개월까지', '고유의 향미가 있고 이미, 이취가 없는 노란색의 내용물을 함유한 투명한 타원형의 연질캡슐', '1일 1회, 1회 2캡슐을 충분한 물과 함께 섭취하십시오.', 'PET(폴리에틸렌테레프탈레이트), PE(폴리에틸렌), HDPE(고밀도폴리에틸렌), PVC(폴리염화비닐), PVDC(폴리염화비닐리덴), 알루미늄호일(Al-Foil)HPE', '[EPA 및 DHA 함유 유지] 혈중 중성지질 개선·혈행 개선·건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음', '실온/ 직사광선과 고온다습한 곳을 피하여 습기가 적고 건조한 곳에 보관하십시오. 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[EPA 및 DHA 함유 유지](가) 의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담할 것(나) 개인에 따라 피부 관련 이상반응이 발생할 수 있음(다) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 9, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200400200142058', 39774, '광동rTG오메가3', '광동rTG오메가3', '광동헬스바이오(주) 2공장', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2025-11-17'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없는 노란색의 내용물을 함유한 투명한 장방형 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장- 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[EPA 및 DHA 함유유지(1) 혈중 중성지질 개선･혈행 개선･건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음[비타민E](1)항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민D](1) 칼슘과 인이 흡수되고 이용되는데 필요(2) 뼈의 형성과 유지에 필요(3) 골다공증발생 위험 감소에 도움을 줌', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '(1) 의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담할 것(2) 개인에 따라 피부 관련 이상반응이 발생할 수 있음(3) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것(5) 본 제품은 원료의 특성상 캡슐 내에 색상 차이나 미세한 입자가 보일 수 있으나, 품질에는 이상이 없습니다.', 10, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200400200073402', 42325, '동국 초임계 알티지 오메가3', '동국 초임계 알티지 오메가3', '(주)한국씨엔에스팜', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2026-04-06'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 노랑색의 내용물을 함유한 투명한 장방형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', 'HDPE, PET, PE, PP, PVC, PVDC, AL-foil', '[EPA 및 DHA 함유 유지]혈중 중성지질 개선･혈행 개선･건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음', '직사광선을 받지 아니하는 서늘한 곳에서 보관 및 유통하시고, 어린이의 손에 닿지 않도록 주의하시기 바랍니다.', '의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담하시기 바랍니다.이상사례 발생 시 섭취를 중단하고 전문가와 상담하시기 바랍니다.개인에 따라 피부 관련 이상반응이 발생할 수 있습니다.', 16, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200700170352816', 33799, '솔가 rTG 알티지 오메가-3 900', '솔가 rTG 알티지 오메가-3 900', '코스맥스엔비티(주)', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2024-11-11'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 투명한 노랑색의 내용물을 함유한 투명한 노랑색 타원형 연질 캡슐', '1일 1회, 1회 2캡슐을 물과 함께 섭취하십시오.', '용기: 폴리에틸렌테레프탈레이트(PET), 고밀도 폴리에틸렌(HDPE), 유리, 뚜껑 : 폴리프로필렌(PP), 리드지 : 폴리에틸렌테레프탈레이트(PET), 에틸렌-초산비닐 공중합체(EVA)', '[비타민 E]항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[EPA 및 DHA 함유 유지]혈중 중성지질 개선･혈행 개선･기억력 개선･건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음', '실온보관 / 1)직사광선이나 고온다습한 곳을 피하여 청결하고 서늘한 곳에 보관하십시오.2)영,유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[EPA 및 DHA 함유 유지]의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담할 것개인에 따라 피부 관련 이상반응이 발생할 수 있음이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 4, '오메가3', '시나리오: P2·P3 오메가3 (대표 제품)'),
  ('200400200021907', 5989, '안국오메가루테인', '안국오메가루테인', '코스맥스바이오(주)', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2016-10-17'::date, '제조일로부터 2년', '적색의 내용물을 함유한 암갈색의 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', 'PTP(염화비닐수지+알루미늄호일), HDPE(고밀도폴리에틸렌), PE(폴리에틸렌), PET(폴리에틸렌테레프탈레이트), PP(폴리프로필렌), PS(폴리스틸렌)', '①혈중 중성지질 개선·혈행 개선·건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음,1) EPA및DHA함유유지 : 건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음, 혈중 중성지질 개선 · 혈행 개선에 도움을 줄 수 있음2) 마리골드꽃추출물 : 노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줌.', '수분 및 열에 의해 영향을 받을 수 있으므로 직사광선을 피해 서늘한 곳에 보관하십시오. 어린이 손에 닿지 않는 곳에 보관하십시오.', '섭취 시 목에 걸릴 수 있으므로 반드시 물과 함께 섭취하십시오. 섭취 시 위장장애, 소화불량의 증상이 있을 경우 섭취를 중단하십시오.개인의 신체 상태에 따라 이상 증상이 생길 경우 섭취를 중단하십시오.섭취 전 제품에 이상이 있는 경우 섭취를 금하십시오.특정 원료 성분에 알레르기 체질은 원료 성분을 확인 후 섭취하십시오.과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있습니다. 의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담하십시오.개인에 따라 피부 관련 이상반응이 발생할 수 있습니다.이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 36, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200400200022100', 7574, '유한 폴리오메가', '유한 폴리오메가', '코스맥스바이오(주)', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2017-12-07'::date, '제조일로부터 2년', '고유의 향미가 있고 이미, 이취가 없으며 연한 노랑색의 내용물을 함유한 어두운 갈색의 장방형 연질캡슐.', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', 'PTP(염화비닐수지+알루미늄호일), HDPE(고밀도폴리에틸렌), PE(폴리에틸렌), PET(폴리에틸렌테레프탈레이트), PP(폴리프로필렌), PS(폴리스틸렌).', '1) 폴리코사놀-사탕수수왁스알코올 : 혈중 콜레스테롤 수치 개선에 도움을 줄 수 있음.2) EPA 및 DHA 함유유지 : 혈중 중성지질 개선 · 혈행 개선에 도움을 줄 수 있음. 3) 비타민E : 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요.,', '수분 및 열에 의해 영향을 받을 수 있으므로 직사광선을 피해 서늘한 곳에 보관하십시오. 어린이 손에 닿지 않는 곳에 보관하십시오.', '섭취 시 목에 걸릴 수 있으므로 반드시 물과 함께 섭취하십시오. 섭취 시 위장장애, 소화불량의 증상이 있을 경우 섭취를 중단하십시오.개인의 신체 상태에 따라 이상 증상이 생길 경우 섭취를 중단하십시오.섭취 전 제품에 이상이 있는 경우 섭취를 금하십시오.특정 원료 성분에 알레르기 체질은 원료 성분을 확인 후 섭취하십시오. 임산부, 수유부, 청소년 및 어린이는 섭취를 피하십시오.심혈관약 등 복용, 혈액응고장애가 있거나 수술예정인 사람은 전문가와 상담하십시오.이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담하십시오.개인에 따라 피부 관련 이상반응이 발생할 수 있습니다.', 9, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200600200081417', 42882, '일동 알티지오메가3 프리미엄', '일동 알티지오메가3 프리미엄', '주식회사 노바렉스2공장', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2026-05-04'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미·이취가 없는 연한 노란 연두의 점도가 있는 내용물을 함유한 투명의 타원형 연질캡슐', '1일 1회, 1회 2캡슐(1캡슐당 650mg)을 물과 함께 섭취하십시오.', '폴리에틸렌테레프탈레이트(PET), 폴리에틸렌(PE), 고밀도폴리에틸렌(HDPE), 저밀도폴리에틸렌(LDPE), 폴리프로필렌(PP), 폴리스틸렌(PS), 폴리염화비닐리덴(PVDC), 폴리염화비닐/알루미늄호일, 알루미늄(AL)', '[EPA 및 DHA 함유 유지] 혈중 중성지질 개선·혈행 개선·기억력 개선·건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음[비타민 D] 칼슘과 인이 흡수되고 이용되는데 필요, 뼈의 형성과 유지에 필요, 골다공증발생 위험 감소에 도움을 줌[비타민 E] 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '1. 고온다습한 곳과 직사광선을 피하여 습기가 적고 건조한 곳에 보관하십시오. 2. 개봉 후에는 공기의 노출을 최대한 차단하여 보관하십시오. 3. 영유아 및 어린이의 손에 닿지 않는 곳에 보관하십시오. 4. 온도 및 습도 등의 변화에 의해 캡슐이 붙는 현상이 발생될 수 있으나, 품질에 이상이 없으니 안심하고 섭취하십시오.', '특정질환, 특이체질, 알레르기체질, 임산부의 경우에는 간혹 개인에 따라 과민반응이 나타날 수 있으므로 원료를 확인하시고, 섭취전에 전문가와 상담하시기 바랍니다.제품 개봉 또는 섭취 시 포장재에 의해 다칠 우려가 있으니 주의하시기 바랍니다.이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[EPA 및 DHA 함유 유지]의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담할 것개인에 따라 피부 관련 이상반응이 발생할 수 있음[비타민 D] 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것', 8, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200400150831624', 19260, '일양약품 rTG 오메가3', '일양약품 rTG 오메가3', '주식회사한미양행', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2022-01-07'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미·이취가 없는 연한 노란 연두색 또는 밝은 노란 연두색의 내용물을 함유한 투명색의 장방형 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취', 'PE, PET, PVC, AL-foil 등', '혈중 중성지질 개선･혈행 개선에 도움을 줄 수 있음항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '고온다습한 곳이나 직사광선을 피하여 서늘한 곳에 보관.', '알레르기 체질이신 경우 성분을 확인 한 후 섭취하시기 바랍니다.[EPA 및 DHA 함유 유지](가) 의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담할 것(나) 개인에 따라 피부 관련 이상반응이 발생할 수 있음(다) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 14, '오메가3', '시나리오: P2·P3 오메가3'),
  ('20040020016706', 41562, '프로메가 알티지 오메가3 듀얼S', '프로메가 알티지 오메가3 듀얼S', '종근당건강(주)', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2026-02-23'::date, '24개월', '고유의 향미가 있고 이미, 이취가 없는 연한 노랑의 내용물을 함유한 투명의 타원형 장용성 연질캡슐', '1일 1회, 1회 2캡슐(0.84g)을 식전, 식후 관계 없이 충분한 물과 함께 섭취하십시오.', 'PVC(폴리염화비닐), 알루미늄호일(Al-Foil), 폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), 폴리프로필렌(PP), 폴리염화비닐리덴(PVDC), 고밀도폴리에틸렌(HDPE)', 'EPA 및 DHA 함유 유지: 혈중 중성지질 개선·혈행 개선에 도움을 줄 수 있음, 건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음비타민E: 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '① 어린이의 손이 닿지 않고, 직사광선을 피해 서늘한 곳에 보관하십시오.', '(가) 의약품(항응고제, 항혈소판제, 혈압강하제 등)복용 시 전문가와 상담하십시오.(나) 개인에 따라 피부 관련 이상반응이 발생할 수 있습니다.(다) 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 38, '오메가3', '시나리오: P2·P3 오메가3 (대표 제품)'),
  ('20190004553117', 12677, '한미 알티지 오메가3', '한미 알티지 오메가3', '주식회사 네추럴웨이 포천 제2공장', '인지기능/기억력, 눈, 혈중 중성지방, 혈행', '2020-05-07'::date, '제조일로부터 24개월', '이미, 이취가 없고, 고유의 향미가 있는 투명한 흰노란색의 내용물을 함유한 투명 연질캡슐', '1일1회, 1회1캡슐을 물과 함께 섭취하십시오.', 'PET, PE, HDPE, PVC, PVDC, AL-foil 등', '[EPA 및 DHA 함유 유지]①혈중 중성지질 개선·혈행 개선에 도움을 줄 수 있음②건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음[비타민E]①항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '실온', '(가) 의약품(항응고제, 항혈소판제, 혈압강하제 등) 복용 시 전문가와 상담할 것(나) 개인에 따라 피부 관련 이상반응이 발생할 수 있음(다) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 6, '오메가3', '시나리오: P2·P3 오메가3'),
  ('200400200142080', 40394, '광동 마그네슘', '광동 마그네슘', '광동헬스바이오(주) 2공장', null, '2025-12-22'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없는 흰색의 장방형 제피정제', '1일 1회, 1회 2정을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장- 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[마그네슘](1) 에너지 이용에 필요(2) 신경과 근육 기능 유지에 필요', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', null, 10, '마그네슘', '시나리오: P3 마그네슘'),
  ('20172880193494', 45317, '동국 액상 마그네슘 트리플샷', '동국 액상 마그네슘 트리플샷', '대원헬스케어 주식회사 2공장', null, '2026-09-08'::date, '제조일로부터 18개월까지', '고유의 향미가 있고 이미, 이취가 없는 진한 노란색의 액상', '1일 1회, 1회 1포를 섭취하십시오.', 'PP(폴리프로필렌), PE(폴리에틸렌)', '[비타민B1] 탄수화물과 에너지 대사에 필요 [비타민B2] 체내 에너지 생성에 필요[비타민B6] 단백질 및 아미노산 이용에 필요 / 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[아연] 정상적인 면역기능에 필요 / 정상적인 세포분열에 필요 [마그네슘] 에너지 이용에 필요 / 신경과 근육 기능 유지에 필요', '직사광선과 고온다습한 곳을 피하여 서늘한 곳에 보관하시고 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[비타민B1]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B2]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B6]손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 56, '마그네슘', '시나리오: P3 마그네슘'),
  ('200700170352315', 23646, '솔가 마그네슘 위드 트리플 B (Magnesium with Triple B)', '솔가 마그네슘 위드 트리플 B (Magnesium with Triple B)', '코스맥스엔비티(주)', null, '2023-01-10'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 흰색 장방형 제피정제', '1일 1회, 1회 2정을 물과 함께 섭취하십시오.', '1. 병: 유리 2. 캡: PP(폴리프로필렌) 3. 리드지: EVA(에틸렌-초산비닐 공중합체)', '[마그네슘]①에너지 이용에 필요②신경과 근육 기능 유지에 필요[비타민B1]탄수화물과 에너지 대사에 필요[비타민B6]①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민B12]정상적인 엽산 대사에 필요', '1) 직사광선이나 고온 다습한 곳을 피하여 청결하고 서늘한 곳에 보관하십시오. 2) 영유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것1) 임산부, 수유부나 의약품을 섭취하시는 분은 섭취 전 전문가와 상담하여 주십시오.2) 특이체질, 알레르기체질인 경우에는 의사와 상담 후 섭취여부를 결정하십시오.3) 섭취량 및 섭취 방법을 확인한 후 섭취하십시오.4) 섭취 전에 소비기한을 확인 후 섭취하십시오. 또한 소비기한이 경과한 제품은 섭취하지 마십시오.', 12, '마그네슘', '시나리오: P3 마그네슘 (대표 제품)'),
  ('200400170212011', 45781, '유한 마그네슘', '유한 마그네슘', '(주)비오팜', null, '2026-10-07'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 하양색의 장방형 제피정제', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', 'PE, PP, PET, PS, PVC, PVDC, AL-Foil', '[마그네슘] (1)에너지 이용에 필요 (2) 신경과 근육 기능 유지에 필요[셀렌] 유해산소로부터 세포를 보호하는데 필요[비타민B6] (1) 단백질 및 아미노산 이용에 필요 (2) 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민B1] 탄수화물과 에너지 대사에 필요[비타민B2] 체내 에너지 생성에 필요', '(1) 직사광선 및 고온 다습한 곳을 피하여 실온에 보관하십시오.(2) 유통 중 인습되지 않도록 포장의 파손에 주의하십시오.(3) 어린이의 손이 닿지 않는 곳에 보관하십시오.', '- 손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것- 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것,- 손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것- 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 26, '마그네슘', '시나리오: P3 마그네슘'),
  ('200400200023346', 24483, '일동 액상마그네슘', '일동 액상마그네슘', '코스맥스바이오(주)', null, '2023-03-16'::date, '제조일로부터 18개월', '고유의 향미가 있고 이미, 이취가 없는 노랑색의 액상', '1일 1회, 1회 1병(25ml)을 섭취하십시오.', 'PE(폴리에틸렌), HDPE(고밀도폴리에틸렌), PET(폴리에틸렌테레프탈레이트), PP(폴리프로필렌), PS(폴리스틸렌), PCT(폴리시클로헥산디메틸렌테레프탈레이트), Al-foil, 유리.', '1) 비타민B1 : 탄수화물과 에너지 대사에 필요2) 비타민B2 : 체내 에너지 생성에 필요3) 비타민B6 : 단백질 및 아미노산 이용에 필요, 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요4) 비타민D : 칼슘과 인이 흡수되고 이용되는데 필요, 뼈의 형성과 유지에 필요, 골다공증발생 위험 감소에 도움을 줌5) 나이아신 : 체내 에너지 생성에 필요6) 마그네슘 : 에너지 이용에 필요, 신경과 근육 기능 유지에 필요7) 아연 : 정상적인 면역기능에 필요, 정상적인 세포분열에 필요', '수분 및 열에 의해 영향을 받을 수 있으므로 직사광선을 피해 서늘한 곳에 보관하십시오. 어린이 손에 닿지 않는 곳에 보관하십시오.', '섭취 시 위장장애, 소화불량의 증상이 있을 경우 섭취를 중단하십시오.개인의 신체 상태에 따라 이상 증상이 생길 경우 섭취를 중단하십시오.섭취 전 제품에 이상이 있는 경우 섭취를 금하십시오.특정 원료 성분에 알레르기 체질은 원료 성분을 확인 후 섭취하십시오.제품 개봉 시 포장재에 의해 상처를 입을 위험이 있고, 개봉 시 내용물이 흘러나올 수 있으므로 취급 시 주의하십시오.고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담하십시오.이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 16, '마그네슘', '시나리오: P3 마그네슘'),
  ('2012001700239', 4368, '종근당파워칼슘앤마그네슘', '종근당파워칼슘앤마그네슘', '이앤에스(주)', null, '2015-02-25'::date, '24개월', '회백색의 원형 정제로 이미, 이취가 없어야한다.', '1일 2회, 1회 1정씩 입안에서 녹이거나 씹어서 섭취하십시오', '용기(PE), 뚜껑(PP), 완충비닐(PE)', '[칼슘]①뼈와 치아 형성에 필요②신경과 근육 기능 유지에 필요③정상적인 혈액응고에 필요④골다공증발생 위험 감소에 도움을 줌
[마그네슘]①에너지 이용에 필요②신경과 근육 기능 유지에 필요
[망간]①뼈 형성에 필요②에너지 이용에 필요③유해산소로부터 세포를 보호하는데 필요
[비타민D]①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌', '직사광선 및 고온다습한 곳을 피해 서늘하고 통풍이 잘 되는 곳에 보관하십시오.', '1. 특정질환, 특이체질, 알레르기 체질인 경우는 간혹 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인 후 섭취하십시오.
2. 유통기한을 확인하시기 바라며, 권장섭취량 및 섭취방법을 준수하시기 바랍니다.
3. 어린이가 섭취할때는 보호자의 관리감독하에 주의하여 섭취시켜 주십시오.', 31, '마그네슘', '시나리오: P3 마그네슘'),
  ('200400200142079', 40365, '광동 비타민D', '광동 비타민D', '광동헬스바이오(주) 2공장', null, '2025-12-19'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없는 투명한 연한 노란색의 내용물을 함유한 빨간색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장- 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[비타민D](1) 칼슘과 인이 흡수되고 이용되는데 필요(2) 뼈의 형성과 유지에 필요(3) 골다공증발생 위험 감소에 도움을 줌', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '(1) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것(3) 본 제품은 원료의 특성상 캡슐 내에 색상 차이나 미세한 입자가 보일 수 있으나 제품의 품질에는 이상이 없으므로 안심하고 섭취하시기 바랍니다.', 7, '비타민D', '시나리오: P3 비타민D'),
  ('200700170351937', 18061, '솔가 면역 비타민D3 2000 위드 아연 (IMMUNE VITAMIN D3 2000IU WITH ZINC)', '솔가 면역 비타민D3 2000 위드 아연 (IMMUNE VITAMIN D3 2000IU WITH ZINC)', '코스맥스엔비티(주)', null, '2021-09-23'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 하얀색의 원형 정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '병포장: 폴리에틸렌(PE), 폴리스틸렌(PS), 고밀도폴리에틸렌(HDPE), 폴리에틸렌테레프탈레이트(PET), 폴리프로필렌(PP), 유리 / 캡: 폴리프로필렌(PP), 저밀도폴리에틸렌(LDPE), 외캡-알루미늄, 내캡-PP(폴리프로필렌)/PE(폴리에틸렌), 씰링지-EVA', '[비타민 D]①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌[아연]①정상적인 면역기능에 필요②정상적인 세포분열에 필요', '실온/ 1. 직사광선을 피해 서늘한 곳에 보관하시고, 어린이의 손이 닿지 않는 곳에 보관하십시오.2. 제품 개봉 후에는 흡습이 일어날 수 있으니 반드시 밀봉하여 보관하십시오.', '1. 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것2. 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것3. 섭취량 및 섭취방법을 확인한 후 섭취하십시오.4. 섭취 전에 소비기한을 확인 후 섭취하십시오. 또한 소비기한이 경과한 제품은 섭취하지 마십시오.5. 제품을 개봉하신 후에는 원료의 특성상 흡습으로 인하여 변질될 수 있으니 섭취 직전에 개봉하여 드시기 바랍니다.6. 강력방습제는 섭취하지 마십시오.', 15, '비타민D', '시나리오: P3 비타민D (대표 제품)'),
  ('20220011370338', 39700, '유한m비타민D2000IU', '유한m비타민D2000IU', '동서바이오팜(주) 안성공장', null, '2025-11-12'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 하양의 내용물이 들어가있는 빨강주황색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', '고밀도폴리에틸렌(HDPE), 폴리에틸렌(PE), 폴리프로필렌(PP), 폴리에틸렌테레프탈레이트(PET), 폴리스티렌(PS), 폴리염화비닐(PVC), 알루미늄호일(AL-Foil)', '(1) 정상적인 면역기능에 필요(2) 정상적인 세포분열에 필요항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요(1) 칼슘과 인이 흡수되고 이용되는데 필요(2) 뼈의 형성과 유지에 필요(3) 골다공증발생 위험 감소에 도움을 줌', '직사광선을 피하여 건조하고 서늘한 곳에 보관하십시오.', '(가) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(나) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 11, '비타민D', '시나리오: P3 비타민D'),
  ('200400170061115', 15880, '일동 비타민D3 5000IU', '일동 비타민D3 5000IU', '(주)알피바이오', null, '2021-03-15'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 연한 노랑색의 내용물을 함유한 적색의 타원형 츄어블 연질캡슐', '1일 1회, 1회 1캡슐을 씹어서 섭취하십시오.', 'HDPE(고밀도폴리에틸렌)병/PVC(염화비닐수지),알루미늄호일/PET(폴리에틸렌테레프탈레이트),PE(폴리에틸렌),PP(폴리프로필렌)', '[비타민D]①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌', '실온/ 고온다습한 곳과 직사광선을 피하여 건조한 곳에 보관하십시오. 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[비타민D](가) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(나) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 30, '비타민D', '시나리오: P3 비타민D'),
  ('20120019007612', 22246, '일양 MSM+비타민D', '일양 MSM+비타민D', '(주)한풍네이처팜', '관절', '2022-09-19'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 백색의 장방형 제피정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), HDPE(고밀도폴리에틸렌), PP(폴리프로필렌), 폴리염화비닐(PVC)+알루미늄호일(AL-FOIL)', '[엠에스엠(MSM)] 관절 및 연골건강에 도움을 줄 수 있음[비타민D] 칼슘과 인이 흡수되고 이용되는데 필요 / 뼈의 형성과 유지에 필요 / 골다공증발생 위험 감소에 도움을 줌', '고온다습(30℃이상, 상대습도 75%이상) · 직사광선을 피하여 서늘한 곳에 보관하십시오. 개봉 후에는 공기의 노출을 최대한 차단하여 보관하십시오.', '특이체질, 알레르기 체질의 경우에는 간혹 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인한 후 섭취하십시오.소비기한을 확인하시기 바라며, 섭취량 및 섭취방법을 준수하시기 바랍니다.신장질환이 있는 사람은 섭취 전 전문가와 상담하십시오.고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담하십시오.이상사례 발생 시 섭취를 중단하고 전문가와 상담하시기 바랍니다.', 29, '비타민D', '시나리오: P3 비타민D'),
  ('200400200071688', 5836, '종근당 비타민D2000IU', '종근당 비타민D2000IU', '(주)한국씨엔에스팜', null, '2016-08-16'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미·이취가 없는 노란 하양색의 내용물을 함유한 적갈색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', 'PE, PET, PVC, AL-foil', '[비타민D] ①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌[아연] ①정상적인 면역기능에 필요②정상적인 세포분열에 필요', '직사광선을 받지 아니하는 서늘한 곳에서 보관 및 유통하시고, 어린이의 손에 닿지 않도록 주의하시기 바랍니다.', '1) 특이체질, 알레르기 체질의 경우 성분를 확인하시고 섭취하여 주시기 바랍니다. 2) 어린이의 경우 섭취 시 목에 걸릴 우려가 있으니 보호자의 지도하에 섭취하시기 바랍니다.3) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 36, '비타민D', '시나리오: P3 비타민D'),
  ('201600060054', 5612, '고려은단멀티비타민', '고려은단멀티비타민', '고려은단 헬스케어(주)', null, '2016-06-15'::date, '24개월', '이미, 이취가 없고 고유의 향미가 있는 백색과 연한 노란색의 층이 있는 이중의 정제', '1일 1회, 1회 1정(1,200mg) 물과 함께 섭취합니다.', 'PE, PVC, AL 등', '[비타민C] ①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요①체내 에너지 생성에 필요①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요①정상적인 엽산 대사에 필요①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①탄수화물과 에너지 대사에 필요①체내 에너지 생성에 필요', '직사광선을 피하고 서늘한 곳에 보관한다.', '(1) 공복에 섭취 시 위장장애로 설사를 유발할 수 있으니 음식물과 함께 섭취하거나 식후에 섭취하십시오. (2) 포장재에 의하여 상처를 입을 수 잇으니 주의가 필요합니다. (3) 알레르기 체질이신 경우 성분을 확인 후 섭취하십시오. (4) 제품이 변질 및 변색된 경우에는 섭취하지 마시고 소비자 상담실로 문의하시기 바랍니다. (5) 임산부와 수유기 여성은 섭취 시 전문가와 상담하시기 바랍니다.(6) 이상 사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 7, '멀티비타민', '시나리오: S6 비타민 추천'),
  ('200400200142064', 39988, '광동 멀티비타민', '광동 멀티비타민', '광동헬스바이오(주) 2공장', null, '2025-11-28'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없으며 점박이가 있는 흰 노란색의 장방형 제피정제', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는 폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장 - 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[비타민C] ①결합조직 형성과 기능유지에 필요 ②철의 흡수에 필요 ③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민E] ①항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[크롬] ①체내 탄수화물, 지방, 단백질 대사에 관여[나이아신] ①체내 에너지 생성에 필요[몰리브덴] ①산화·환원 효소의 활성에 필요[아연] ①정상적인 면역기능에 필요 ②정상적인 세포분열에 필요[망간] ①뼈 형성에 필요 ②에너지 이용에 필요 ③유해산소로부터 세포를 보호하는데 필요[비타민A] ①어두운 곳에서 시각 적응을 위해 필요 ②피부와 점막을 형성하고 기능을 유지하는데 필요 ③상피세포의 성장과 발달에 필요[판토텐산] ①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[비타민D] ①칼슘과 인이 흡수되고 이용되는데 필요 ②뼈의 형성과 유지에 필요 ③골다공증발생 위험 감소에 도움을 줌[비오틴] ①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[구리] ①철의 운반과 이용에 필요 ②유해산소로부터 세포를 보호하는데 필요[비타민B12] ①정상적인 엽산 대사에 필요[비타민B6] ①단백질 및 아미노산 이용에 필요 ②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민K] ①정상적인 혈액응고에 필요 ②뼈의 구성에 필요[비타민B1] ①탄수화물과 에너지 대사에 필요[비타민B2] ①체내 에너지 생성에 필요[엽산] ①세포와 혈액생성에 필요 ②태아 신경관의 정상 발달에 필요 ③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '[비타민C]① 과량 섭취하지 않도록 주의할 것② 신장질환이 있는 경우 섭취 전 전문가와 상담할 것③ 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[크롬]① 당뇨병이 있는 경우 섭취 전 전문가와 상담할 것② 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[판토텐산/비타민B12/비오틴/비타민B1/비타민B2]① 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민D]① 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것② 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B6]① 손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민K]① 항응고제 등 복용 시 전문가와 상담할 것② 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 161, '멀티비타민', '시나리오: S6 비타민 추천'),
  ('2004001710680', 548, '대웅 액티브 멀티비타민&미네랄 포맨', '대웅 액티브 멀티비타민&미네랄 포맨', '에스케이내추럴팜(주)', null, '2008-07-29'::date, '24개월', '연한회백색의 원형 정제로 이미, 이취가 없다.', '1일 1회, 1회 1정을 씹어서 섭취', 'PE(폴리에틸렌) 병', '①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③유해산소로부터 세포를 보호하는데 필요
