  ('200700170353276', 44848, '센트룸 데일리 뉴트리션 팩 30 여성 프로 Centrum Daily Nutrition Pack 30 Women Pro', '센트룸 데일리 뉴트리션 팩 30 여성 프로 Centrum Daily Nutrition Pack 30 Women Pro', '코스맥스엔비티(주)', '체지방, 콜레스테롤, 항산화', '2026-08-18'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 정제1 - 고유의 향미가 있고, 이미 이취가 없는 회갈색의 장방형 제피정제 정제2 - 고유의 향미가 있고 이미, 이취가 없는 흐린 황갈색의 장방형 제피정제 정제3 - 고유의 향미가 있고 이미, 이취가 없으며 흰색 점박이가 있는 갈색 장타원형 투명 제피 정제 정제4 - 고유의 향미가 있고 이미, 이취가 없는 분홍색 장방형 제피 정제', '1일 1회, 1회 1포를 물과 함께 섭취하십시오.', '폴리에틸렌(PE)', '[비타민 A]어두운 곳에서 시각 적응을 위해 필요피부와 점막을 형성하고 기능을 유지하는데 필요상피세포의 성장과 발달에 필요[비타민 D]칼슘과 인이 흡수되고 이용되는데 필요뼈의 형성과 유지에 필요골다공증발생 위험 감소에 도움을 줌[비타민 K]정상적인 혈액응고에 필요뼈의 구성에 필요[비타민 E]항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민 B1]탄수화물과 에너지 대사에 필요[비타민 B2]체내 에너지 생성에 필요[나이아신]체내 에너지 생성에 필요[판토텐산]지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[비타민 B6]단백질 및 아미노산 이용에 필요혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[엽산]세포와 혈액생성에 필요태아 신경관의 정상 발달에 필요혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민 B12]정상적인 엽산 대사에 필요[비오틴]지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[비타민 C]결합조직 형성과 기능유지에 필요철의 흡수에 필요항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[칼슘]뼈와 치아 형성에 필요신경과 근육 기능 유지에 필요정상적인 혈액응고에 필요골다공증발생 위험 감소에 도움을 줌[마그네슘]에너지 이용에 필요신경과 근육 기능 유지에 필요[철]체내 산소운반과 혈액생성에 필요에너지 생성에 필요[아연]정상적인 면역기능에 필요정상적인 세포분열에 필요[구리]철의 운반과 이용에 필요유해산소로부터 세포를 보호하는데 필요[셀레늄(또는 셀렌)]유해산소로부터 세포를 보호하는데 필요[망간]뼈 형성에 필요에너지 이용에 필요유해산소로부터 세포를 보호하는데 필요[몰리브덴]산화 ･환원 효소의 활성에 필요[크롬]체내 탄수화물, 지방, 단백질 대사에 관여[녹차추출물]항산화･체지방 감소･혈중 콜레스테롤 개선에 도움을 줄 수 있음', '실온보관 / 1)직사광선이나 고온다습한 곳을 피하여 청결하고 서늘한 곳에 보관하십시오.2)영,유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[비타민 D]고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 K]항응고제 등 복용 시 전문가와 상담할 것이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 B1]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 B2]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[판토텐산]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 B6]손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 B12]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비오틴]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민 C]과량 섭취하지 않도록 주의할 것신장질환이 있는 경우 섭취 전 전문가와 상담할 것이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[철]특히 6세 이하는 과량섭취하지 않도록 주의[크롬]당뇨병이 있는 경우 섭취 전 전문가와 상담할 것이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[녹차추출물]어린이, 임산부 및 수유부는 섭취를 피할 것간질환이 있거나 의약품 복용 시 전문가와 상담할 것카페인이 함유되어 있어 초조감, 불면 등을 나타낼 수 있음식사 후 섭취할 것카페인을 함유한 식품의 섭취에 주의할 것이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 45, '멀티비타민', '시나리오: S6 비타민 추천 (대표 제품)'),
  ('20172880193226', 28878, '유한양행 종합비타민', '유한양행 종합비타민', '대원헬스케어 주식회사 2공장', null, '2023-12-28'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 적갈색의 장방형 제피정제', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', '고밀도폴리에틸렌(HDPE), 알루미늄호일(AL-Foil)+염화비닐수지(PVC), 폴리에틸렌(PE), 폴리프로필렌(PP), 폴리에틸렌테레프탈레이트(PET), 폴리스티렌(PS) 등', '비타민 C - ①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요비타민 E - 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요크롬 - (1) 체내 탄수화물, 지방, 단백질 대사에 관여나이아신 - ①체내 에너지 생성에 필요몰리브덴 -산화·환원 효소의 활성에 필요아연 - ①정상적인 면역기능에 필요②정상적인 세포분열에 필요망간 - ①뼈 형성에 필요②에너지 이용에 필요③유해산소로부터 세포를 보호하는데 필요비타민 A - ①어두운 곳에서 시각 적응을 위해 필요②피부와 점막을 형성하고 기능을 유지하는데 필요③상피세포의 성장과 발달에 필요판토텐산 - (1) 지방, 탄수화물, 단백질 대사와 에너지 생성에 필요셀레늄(또는 셀렌) - ①유해산소로부터 세포를 보호하는데 필요비타민 D - ①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌비오틴 - (1) 지방, 탄수화물, 단백질 대사와 에너지 생성에 필요구리 - ①철의 운반과 이용에 필요②유해산소로부터 세포를 보호하는데 필요비타민B12 - (1) 정상적인 엽산 대사에 필요비타민B6 - ①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요비타민 K - (1) 정상적인 혈액응고에 필요 (2) 뼈의 구성에 필요비타민 B1 - (1) 탄수화물과 에너지 대사에 필요비타민B2 - (1) 체내 에너지 생성에 필요엽산 - ①세포와 혈액생성에 필요②태아 신경관의 정상 발달에 필요③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요요오드 - ①갑상선 호르몬의 합성에 필요②에너지 생성에 필요③신경발달에 필요', '습기 및 열에 의해 품질에 영향을 받을 수 있으므로 직사광선을 피해서 실온에 보관하시고, 개봉 후에는 공기의 노출을 최대한 차단하여 보관 하십시오.', '크롬-(1) 당뇨병이 있는 경우 섭취 전 전문가와 상담할 것 (2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 D-(가) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것 (나) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 B1-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 B2-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 K-(1) 항응고제 등 복용 시 전문가와 상담할 것 (2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 B12-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것판토텐산-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비오틴-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것,크롬-(1) 당뇨병이 있는 경우 섭취 전 전문가와 상담할 것 (2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 D-(가) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것 (나) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 B1-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 B2-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 K-(1) 항응고제 등 복용 시 전문가와 상담할 것 (2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비타민 B12-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것판토텐산-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것비오틴-(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 30, '멀티비타민', '시나리오: S6 비타민 추천'),
  ('20120017002128', 10741, '일양 멀티비타민', '일양 멀티비타민', '이앤에스(주)', null, '2019-08-23'::date, '24 개월', '고유의 향미가 있고 이미, 이취가 없으며 무광택의 연노란색의 원형 정제', '1일 1회, 1회 1정씩 입안에서 녹이거나, 씹어서 섭취하십시오.', 'HDPE, PE, PET', '①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③유해산소로부터 세포를 보호하는데 필요① 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요①체내 에너지 생성에 필요①정상적인 면역기능에 필요②정상적인 세포분열에 필요①어두운 곳에서 시각 적응을 위해 필요②피부와 점막을 형성하고 기능을 유지하는데 필요③상피세포의 성장과 발달에 필요①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요①칼슘과 인이 흡수되고 이용되는데 필요②뼈의 형성과 유지에 필요③골다공증발생 위험 감소에 도움을 줌①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①뼈 형성에 필요②에너지 이용에 필요③유해산소로부터 세포를 보호하는데 필요①탄수화물과 에너지 대사에 필요①체내 에너지 생성에 필요①정상적인 엽산 대사에 필요①산화,환원 효소의 활성에 필요', '본 제품은 직사광선을 피하고 흡습으로 인해 정제 색상이 변할 수 있으므로 습기가 적고, 건조하고 서늘한 실온에 보관하십시오.', '1) 특정질환, 특이체질, 알레르기 체질인 경우 개인에 따라 과민반응을 나타낼 수 있으므로 원료를 확인 후 섭취하십시오.2) 어린이가 섭취 할 때는 보호자의 관리 감독 하에 주의하여 섭취시켜 주십시오.3) 고칼슘혈증이 있거나 의약품복용 시 전문가와 상담하십시오.4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.5) 용기안의 방습제는 드시지 마십시오.', 61, '멀티비타민', '시나리오: S6 비타민 추천'),
  ('2004001706252', 1515, '종근당건강멀티비타민포맨', '종근당건강멀티비타민포맨', '(주)에스엘에스', null, '2011-01-31'::date, '24개월', '노란색의 원형정제로 이미,이취가 없음', '1일 1회, 1회 1정씩 씹어서 섭취하십시오.', 'PE(폴리에틸렌수지)', '[비타민A]①어두운 곳에서 시각 적응을 위해 필요②피부와 점막을 형성하고 기능을 유지하는데 필요③상피세포의 성장과 발달에 필요[비타민E]①항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민B1]①탄수화물과 에너지 대사에 필요[비타민B2]①체내 에너지 생성에 필요[나이아신]①체내 에너지 생성에 필요[비타민B6]①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[엽산]①세포와 혈액생성에 필요②태아 신경관의 정상 발달에 필요③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민C]①결합조직 형성과 기능유지에 필요②철의 흡수에 필요③ 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '어린이의 손이 닿지 않고, 직사광선을 피해 서늘한 곳에 보관하십시오.', '1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.2) 알레르기 체질이신 분은 성분을 확인 후 섭취하여 주십시오. 3) 섭취량 및 섭취방법을 확인하시고 섭취하여 주십시오.4) 유통기한이 경과된 제품은 섭취하지 않도록 주의 바랍니다.5) 흡습의 우려가 있으니 개봉한 제품은 바로 섭취하십시오.6) 용기 개봉 후에는 원료의 특성(흡습성)으로 인하여 색상이 진해지거나 눅눅해질 수 있으니 뚜껑을 꼭 닫아주십시오.7) 임산부, 수유부, 만성질환이 있거나 현재 질병치료 중이신 분은 전문의와 상의 후 섭취하십시오.8) 용기내의 방습제는 드시지 마십시오.', 45, '멀티비타민', '시나리오: S6 비타민 추천'),
  ('20040015083451', 1173, '한미멀티비타민', '한미멀티비타민', '주식회사한미양행', null, '2010-06-09'::date, '제조일로부터 24개월까지', '고유의 향미를 지니고 이미, 이취가 없는 분홍색의 원형 정제.', '1일 3회, 1회 1정씩 씹거나 녹여서 섭취.', '폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), 폴리스티렌(PS)', '[비타민A] ①어두운 곳에서 시각 적응을 위해 필요 ②피부와 점막을 형성하고 기능을 유지하는데 필요 ③상피세포의 성장과 발달에 필요[비타민C] ①결합조직 형성과 기능유지에 필요 ②철의 흡수에 필요 ③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민D] ①칼슘과 인이 흡수되고 이용되는데 필요 ②뼈의 형성과 유지에 필요 ③골다공증발생 위험 감소에 도움을 줌[비타민B1] ①탄수화물과 에너지 대사에 필요[비타민E] ①항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '고온다습한 곳이나 직사광선을 피하여 서늘한 곳에 보관.', '(가) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(나) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것알레르기 체질이신 경우 성분을 확인 한 후 섭취하시기 바랍니다.', 28, '멀티비타민', '시나리오: S6 비타민 추천'),
  ('200400200142094', 41046, '광동 비타민B', '광동 비타민B', '광동헬스바이오(주) 2공장', null, '2026-01-26'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없으며 점박이가 있는 흰 노란색의 장방형 제피정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장- 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[나이아신](1) 체내 에너지 생성에 필요[판토텐산](1) 지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[비오틴](1) 지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[비타민B12](1) 정상적인 엽산 대사에 필요[비타민B6](1) 단백질 및 아미노산 이용에 필요(2) 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민B1](1) 탄수화물과 에너지 대사에 필요[비타민B2](1) 체내 에너지 생성에 필요[엽산](1) 세포와 혈액생성에 필요(2) 태아 신경관의 정상 발달에 필요(3) 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '[판토텐산](1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비오틴](1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B12](1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B6](1) 손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B1](1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B2](1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 16, '비타민B', '시나리오: S6 비타민 추천(피로)'),
  ('20040017017967', 5923, '듀오락 비타민B복합 프로바이오틱스', '듀오락 비타민B복합 프로바이오틱스', '(주)쎌바이오텍', '장', '2016-09-21'::date, '제조일로부터 24개월', '고유의 향미를 가지며 이미, 이취가 없는 흐린 노란 주황색의 분말을 함유한 흰색의 장방형 경질캡슐', '1일 1회, 1회 2캡슐(0.9g)을 물과 함께 섭취하십시오.', '내포장재질-폴리에틸렌(PE)', '①유산균 증식 및 유해균 억제에 도움을 줄 수 있음 ②배변활동 원활에 도움을 줄 수 있음 ①탄수화물과 에너지 대사에 필요①체내 에너지 생성에 필요①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요', '습기, 일광을 피하여 서늘한 곳에 보관, 유통하십시오.', '1) 질환이 있거나 의약품 복용 시 전문가와 상담할 것.2) 알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음.3) 어린이가 함부로 섭취하지 않도록 일일 섭취량 방법을 지도할 것.4) 이상 사례 발생시 섭취를 중단하고 전문가와 상담할 것.', 19, '비타민B', '시나리오: S6 비타민 추천(피로)'),
  ('200700170352409', 25256, '레모나 비오틴+비타민B군 구미', '레모나 비오틴+비타민B군 구미', '코스맥스엔비티(주)', null, '2023-05-01'::date, '제조일로부터 18개월', '고유의 향미가 있고 이미, 이취가 없는 진한 분홍색의 반원 모양 젤리', '1일 1회, 1회 2개를 씹어서 섭취하십시오.', '①병 : 폴리에틸렌(PE), 고밀도폴리에틸렌(HDPE), 폴리에틸렌테레프탈레이트(PET)②캡 : 폴리프로필렌(PP)', '[비타민B1]①탄수화물과 에너지 대사에 필요[비타민B6]① 단백질 및 아미노산 이용에 필요② 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비오틴]①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요', '1) 제품이 고온에 약하니 직사광선을 피하여 실온의 온, 습도가 낮은 곳에 보관하십시오.2) 개봉한 제품은 변질의 우려가 있으니 밀봉하여 보관하시고 가급적 빨리 섭취하십시오.', '이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 38, '비타민B', '시나리오: S6 비타민 추천(피로)'),
  ('200400200073258', 35363, '여에스더 비타민B 컴플렉스', '여에스더 비타민B 컴플렉스', '(주)한국씨엔에스팜', null, '2025-03-04'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미·이취가 없는 노란색의 장방형 제피 정제', '1일 1회, 1회 2정을 충분한 물과 함께 섭취하십시오.', 'HDPE, PET, PE, PP, PVC, AL-foil', '[비타민B1] ①탄수화물과 에너지 대사에 필요[판토텐산] ①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[나이아신] ①체내 에너지 생성에 필요[비타민B6] ①단백질 및 아미노산 이용에 필요 ②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민B2] ①체내 에너지 생성에 필요[비타민B12] ①정상적인 엽산 대사에 필요[비오틴] ①지방, 탄수화물, 단백질 대사와 에너지 생성에 필요[엽산] ①세포와 혈액생성에 필요 ②태아 신경관의 정상 발달에 필요 ③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요', '직사광선을 받지 아니하는 서늘한 곳에서 보관 및 유통하시고, 어린이의 손에 닿지 않도록 주의하시기 바랍니다.', '① 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.② 손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담하시기 바랍니다.', 15, '비타민B', '시나리오: S6 비타민 추천(피로)'),
  ('200400150831745', 21836, '한미양행 비오 비타민B 컴플렉스', '한미양행 비오 비타민B 컴플렉스', '주식회사한미양행', null, '2022-08-09'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 밝은 노란 주황 또는 진한 노란색의 타원형 정제.', '1일 1회, 1회 1정을 물과 함께 섭취.', 'PVC(염화비닐수지), AL-foil(알미늄호일), PE(폴리에틸렌), PET(폴리에틸렌테레프탈레이트) 등.', '(1) 탄수화물과 에너지 대사에 필요(1) 체내 에너지 생성에 필요①체내 에너지 생성에 필요(1) 지방, 탄수화물, 단백질 대사와 에너지 생성에 필요①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①세포와 혈액생성에 필요②태아 신경관의 정상 발달에 필요③혈액의 호모시스테인 수준을 정상으로 유지하는데 필요(1) 정상적인 엽산 대사에 필요(1) 지방, 탄수화물, 단백질 대사와 에너지 생성에 필요①정상적인 면역기능에 필요②정상적인 세포분열에 필요①유해산소로부터 세포를 보호하는데 필요', '고온다습한 곳이나 직사광선을 피하여 서늘한 곳에 보관.', '(1) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것알레르기 체질이신 경우 성분을 확인 한 후 섭취하시기 바랍니다.', 15, '비타민B', '시나리오: S6 비타민 추천(피로)'),
