  ('20040020016703', 41177, '락토핏 플러스 프로바이오틱스', '락토핏 플러스 프로바이오틱스', '종근당건강(주)', '장', '2026-01-30'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 흰보라색의 분말', '1일 2회, 1회 1포를 식전·식후 어느때나 물 없이 섭취하십시오.', '폴리에틸렌(PE)', '유산균 증식 및 유해균 억제･배변활동 원활･장 건강에 도움을 줄 수 있음', '어린이의 손이 닿지 않고, 직사광선을 피해 서늘한 곳에 보관하십시오.', '(가) 질환이 있거나 의약품 복용 시 전문가와 상담할 것(나) 알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음(다) 어린이가 함부로 섭취하지 않도록 일일섭취량 방법을 지도할 것(라) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 74, '유산균', '자주 먹는 영양제 (대표 제품)'),
  ('200600200032607', 23366, '센트룸 프로바이오 면역케어', '센트룸 프로바이오 면역케어', '콜마비앤에이치(주)음성공장', '면역, 면역', '2022-12-19'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 노란 하얀색 또는 흰 노란색의 분말을 함유한 흰색의 경질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '폴리프로필렌(PP), 폴리에틸렌(PE), 저밀도폴리에틸렌(LDPE), 고밀도폴리에틸렌(HDPE), 폴리스틸렌(PS), 폴리에틸렌테레프탈레이트(PET), 알루미늄(Al)', '- 베타글루칸분말 : 면역기능 증진에 도움을 줄 수 있음- 프로바이오틱스 : 유산균 증식 및 유해균 억제 · 배변활동 원활 · 장 건강에 도움을 줄 수 있음- 아연 : 정상적인 면역기능에 필요, 정상적인 세포분열에 필요- 셀렌 : 유해산소로부터 세포를 보호하는데 필요', '건조하고 서늘한 곳에 보관', '1) 영·유아, 어린이, 임산부 및 수유부는 섭취에 주의2) 특정질환(알레르기 체질 등)이 있는 분은 섭취에 주의3) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것4) 질환이 있거나 의약품 복용 시 전문가와 상담할 것5) 알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음6) 어린이가 함부로 섭취하지 않도록 일일섭취량 방법을 지도할 것', 12, '유산균', '자주 먹는 영양제'),
