  ('20040015110711', 7770, '일동 생유산균', '일동 생유산균', '주)팜크로스', '장', '2018-01-18'::date, '제조일로부터 18개월.', '이미, 이취가 없고 고유의 향미가 있는 연분홍색의 분말', '1일 1회, 1회 1포를 직접 또는 물과 함께 섭취하십시오.', '폴리에틸렌(PE)', '①유산균 증식 및 유해균 억제에 도움을 줄 수 있음 ②배변활동 원활에 도움을 줄 수 있음 ①정상적인 면역기능에 필요②정상적인 세포분열에 필요', '직사광선 및 고온다습한 곳을 피하여 건조하고 서늘한 곳에 보관하십시오.', '특정질환이 있거나 특이체질, 알레르기 체질이신 분은 섭취 전 원료명을 확인하시고 의사, 약사 등 전문가와 상담 후 섭취여부를 결정하십시오. 섭취자의 신체 상태에 따라 특이반응이 나타날 경우 섭취를 중단하십시오. 어린이의 경우 보호자의 보호 아래 섭취시켜 주십시오. 제품 개봉 시 포장재에 의해 상처를 입을 수 있으니 주의하십시오', 42, '유산균', '자주 먹는 영양제'),
