  ('20040017014592', 13618, '종근당(鍾根堂)바이오 발효홍삼유산균', '종근당(鍾根堂)바이오 발효홍삼유산균', '(주)뉴팜', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2020-08-07'::date, '제조일로부터 18개월', '이미, 이취가 없고 고유의 향미가 있는 연갈색의 분말', '1일 1회, 1회 2포를 직접 또는 물과 함께 섭취하십시오.', '폴리에틸렌(PE)', '①면역력 증진·피로개선·혈소판 응집억제를 통한 혈액흐름·기억력 개선·항산화에 도움을 줄 수 있음유산균 증식 및 유해균 억제·배변활동 원활에 도움을 줄 수 있음', '직사광선을 피하여 서늘한 곳에 보존하고, 유통 중 흡습되지 않도록 포장의 파손 등에 주의하여야 한다.', '의약품(당뇨치료제, 혈액항응고제) 복용 시 섭취에 주의(가) 질환이 있거나 의약품 복용 시 전문가와 상담할 것(나) 알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음(다) 어린이가 함부로 섭취하지 않도록 일일섭취량 방법을 지도할 것(라) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것,의약품(당뇨치료제, 혈액항응고제) 복용 시 섭취에 주의(가) 질환이 있거나 의약품 복용 시 전문가와 상담할 것(나) 알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음(다) 어린이가 함부로 섭취하지 않도록 일일섭취량 방법을 지도할 것(라) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 23, '유산균', '자주 먹는 영양제'),
  ('20130020024465', 36222, '고려은단 루테인 지아잔틴 아스타잔틴', '고려은단 루테인 지아잔틴 아스타잔틴', '(주)서흥헬스케어', '눈, 눈', '2025-04-23'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 어두운 빨강의 점도가 있는 내용물을 함유한 흑갈색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', '폴리염화비닐리덴(PVDC), 폴리염화비닐(PVC), 알루미늄호일(Al-foil)', '루테인지아잔틴복합추출물(제2019-16호) : (국문) 노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음 (영문) May help the eye health by maintaining the density of macular pigments which can be decreased by aging헤마토코쿠스 추출물 : 눈의 피로도 개선에 도움을 줄 수 있음비타민A : (1) 어두운 곳에서 시각 적응을 위해 필요 (2) 피부와 점막을 형성하고 기능을 유지하는데 필요 (3) 상피세포의 성장과 발달에 필요', '제품은 직사광선을 피하고 실온에서 보관 유통하십시오.', '(1) 영·유아, 어린이, 임산부 및 수유부는 섭취를 피할 것(2) 흡연자는 섭취 시 전문가와 상담할 것(3) 과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있음(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것(5) β-카로틴의 흡수를 저해할 수 있음', 9, '루테인', '자주 먹는 영양제'),
  ('200400200142059', 39798, '광동 루테인', '광동 루테인', '광동헬스바이오(주) 2공장', '눈', '2025-11-18'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없으며 밝은 적갈색의 내용물을 함유한 진한 적갈색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는 폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE)/PTP포장 - 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[마리골드꽃추출물] 노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음[비타민C] ①결합조직 형성과 기능유지에 필요 ②철의 흡수에 필요 ③항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[셀렌] 유해산소로부터 세포를 보호하는데 필요[아연] ①정상적인 면역기능에 필요 ②정상적인 세포분열에 필요[비타민E] 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민A] ①어두운 곳에서 시각 적응을 위해 필요 ②피부와 점막을 형성하고 기능을 유지하는데 필요 ③상피세포의 성장과 발달에 필요[비타민D] ①칼슘과 인이 흡수되고 이용되는데 필요 ②뼈의 형성과 유지에 필요 ③골다공증발생 위험 감소에 도움을 줌', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '[마리골드꽃추출물] (1) 영‧유아, 어린이, 임산부 및 수유부는 섭취를 피할 것(2) 흡연자는 섭취 시 전문가와 상담할 것(3) 과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있음(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민C](1) 과량 섭취하지 않도록 주의할 것(2) 신장질환이 있는 경우 섭취 전 전문가와 상담할 것(3) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민D](1) 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것(2) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 66, '루테인', '자주 먹는 영양제'),
  ('200400170061930', 43404, '동국 루테인지아잔틴', '동국 루테인지아잔틴', '(주)알피바이오', null, '2026-05-29'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 진한 빨간색의 내용물을 함유한 진한 적갈색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', 'PVC(폴리염화비닐), PVDC(폴리염화비닐리덴), 알루미늄호일(Al-Foil), PP(폴리프로필렌) 등', '⌜건강기능식품의 기준 및 규격⌟ 제3.2.2-26 마리골드꽃추출물에 따름[마리골드꽃추출물](1) 노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음[비타민 A](1) 어두운 곳에서 시각 적응을 위해 필요(2) 피부와 점막을 형성하고 기능을 유지하는데 필요(3) 상피세포의 성장과 발달에 필요', '실온/직사광선과 고온다습한 곳을 피하여 습기가 적고 건조한 곳에 보관하십시오, 어린이의 손이 닿지 않는 곳에 보관하십시오.', '⌜건강기능식품의 기준 및 규격⌟ 제3.2.2-26 마리골드꽃추출물에 따름[마리골드꽃추출물](1) 영·유아, 어린이, 임산부 및 수유부는 섭취를 피할 것(2) 흡연자는 섭취 시 전문가와 상담할 것(3) 과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있음(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 7, '루테인', '자주 먹는 영양제'),
  ('200400200061434', 11500, '유한 루테인지아잔틴', '유한 루테인지아잔틴', '(주)서흥', '눈, 눈', '2019-12-17'::date, '제조일부터 36개월', '고유의 향미가 있고 이미, 이취가 없는 빨간 주황의 점도가 있는 내용물을 함유한 흑갈색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', '폴리염화비닐리덴(PVDC), 폴리염화비닐(PVC), 알루미늄호일(Al-foil)', '루테인지아잔틴복합추출물 : (국문) 노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음, 건조한 눈을 개선하여 눈 건강에 도움을 줄 수 있음 (영문) May help the eye health by maintaining the density of macular pigments which can be decreased by aging, May help to maintain eyes healthy by relieving dryness비타민 E : 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요', '- 고온다습한 곳이나 직사광선을 피하여 서늘한 곳에 보관하십시오. - 어린이 손에 닿지 않는 곳에 보관하십시오.', '(1) 영·유아, 어린이, 임산부 및 수유부는 섭취를 피할 것(2) 흡연자는 섭취 시 전문가와 상담할 것(3) 과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있음(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것(5) 특정 성분에 알레르기가 있으신 분은 원료명을 확인 후 섭취할 것(6) 개봉 또는 섭취 시 포장재에 의해 상처를 입을 수 있으니 주의할 것', 10, '루테인', '자주 먹는 영양제'),
  ('200400170061917', 42848, '일동 루테인케어', '일동 루테인케어', '(주)알피바이오', null, '2026-04-30'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없으며 적색의 내용물을 함유한 빨간 검정색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오', 'PVC(폴리염화비닐), PVDC(폴리염화비닐리덴), 알루미늄호일(Al-Foil) 등', '[루테인지아잔틴복합추출물(제2019-16호)](국문) 노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음(영문) May help the eye health by maintaining the density of macular pigments which can be decreased by aging[헤마토코쿠스 추출물](1) 기능성 내용 : 눈의 피로도 개선에 도움을 줄 수 있음[비타민 A](1) 어두운 곳에서 시각 적응을 위해 필요(2) 피부와 점막을 형성하고 기능을 유지하는데 필요(3) 상피세포의 성장과 발달에 필요[비타민 E](1) 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[비타민 C](1) 결합조직 형성과 기능유지에 필요(2) 철의 흡수에 필요(3) 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[아연](1) 정상적인 면역기능에 필요(2) 정상적인 세포분열에 필요', '실온 / 직사광선 및 고온다습한 곳을 피하여 보관·유통하십시오. 유통 및 소비 중 변질되지 않도록 포장의 파손 등에 주의하십시오. 영유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[루테인지아잔틴복합추출물(제2019-16호)](1) 영유아, 어린이, 임산부 및 수유부는 섭취를 피할 것(2) 흡연자는 섭취 시 전문가와 상담할 것(3) 과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있음(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[헤마토코쿠스 추출물](1) 과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있음(2) β-카로틴의 흡수를 저해할 수 있음[비타민 C](1) 과량 섭취하지 않도록 주의할 것(2) 신장질환이 있는 경우 섭취 전 전문가와 상담할 것(3) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 46, '루테인', '자주 먹는 영양제'),
  ('20040017068156', 4743, '일양루테인플러스', '일양루테인플러스', '일양약품(주)', null, '2015-07-24'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미·이취가 없는 밝은 적갈색 내용물을 함유한 어두운 적색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오', 'PTP(염화비닐수지+알루미늄호일), HDPE(고밀도폴리에틸렌), PE(폴리에틸렌), PET(폴리에틸렌테레프탈레이트), PP(폴리프로필렌), PS(폴리스틸렌), AL(알루미늄), 유리, 철', '①노화로 인해 감소될 수 있는 황반색소밀도를 유지하여 눈 건강에 도움을 줄 수 있음①어두운 곳에서 시각 적응을 위해 필요②피부와 점막을 형성하고 기능을 유지하는데 필요③상피세포의 성장과 발달에 필요①정상적인 면역기능에 필요②정상적인 세포분열에 필요①항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요①어두운 곳에서 시각 적응을 위해 필요②피부와 점막을 형성하고 기능을 유지하는데 필요③상피세포의 성장과 발달에 필요', '1)수분, 열에 의해 품질에 영향을 받을 수 있으므로 직사광선을 피해 서늘한 곳에 보관하십시오. 2) 어린이 손에 닿지 않는 곳에 보관하십시오. 3) 본 제품은 동물성 젤라틴이 아닌 식물 유래 성분으로 캡슐 피막을 제조한 제품으로, 던지거나 심한 충격을 가할 경우 캡슐이 파손될 수 있으니 주의바랍니다.', '영·유아,어린이, 임산부 및 수유부는 섭취를 피하십시오.흡연자는 섭취 시 전문가와 상담하십시오.과다 섭취 시 일시적으로 피부가 황색으로 변할 수 있습니다.이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.섭취 시 목에 걸리거나 불편할 수 있으므로 반드시 물과 함께 섭취하십시오.섭취 시 위장장애, 소화불량의 증상이 있을 경우 섭취를 중단하십시오.섭취 전 제품에 이상이 있는 경우 섭취를 금하십시오.특이체질, 알레르기 체질인 경우 간혹 개인에 따라 과민반응을 나타낼 수 있으므로 확인 후 섭취하십시오.', 24, '루테인', '자주 먹는 영양제'),
  ('200400200142069', 40104, '광동 밀크씨슬', '광동 밀크씨슬', '광동헬스바이오(주) 2공장', '간', '2025-12-04'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미.이취가 없으며 점박이가 있는 밝은 회황색의 장방형 제피정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE), PTP포장- 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[밀크씨슬추출물] 간 건강에 도움을 줄 수 있음', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '[밀크씨슬추출물](1) 어린이, 임산부 및 수유부는 섭취를 피할 것(2) 알레르기 반응이 나타나는 경우에는 섭취 중단(3) 설사, 위통, 복부팽만 등의 위장관계 장애가 나타나는 경우에는 섭취에 주의(4) 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 9, '밀크씨슬', '자주 먹는 영양제'),
  ('200400200073369', 40613, '동국 밀크씨슬', '동국 밀크씨슬', '(주)한국씨엔에스팜', '간', '2026-01-05'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 연한 노랑색의 타원형 제피정제', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', 'HDPE, PET, PE, PP, PVC, AL-foil', '[밀크씨슬 추출물] 간 건강에 도움을 줄 수 있음', '직사광선을 받지 아니하는 서늘한 곳에서 보관 및 유통하시고, 어린이의 손에 닿지 않도록 주의하시기 바랍니다.', '-어린이, 임산부 및 수유부는 섭취를 피하십시오.-알레르기 반응이 나타나는 경우에는 섭취 중단하십시오.-설사, 위통, 복부팽만 등의 위장관계 장애가 나타나는 경우에는 섭취에 주의하십시오.-이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 55, '밀크씨슬', '자주 먹는 영양제'),
  ('200700170351816', 16078, '솔가 밀크씨슬 130', '솔가 밀크씨슬 130', '코스맥스엔비티(주)', '간', '2021-03-31'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 회황색의 내용물을 함유한 투명한 장방형 경질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '병포장: 폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), 폴리스틸렌(PS), 고밀도폴리에틸렌(HDPE), 폴리프로필렌(PP), 유리, 폴리프로필렌(PP), 저밀도폴리에틸렌(LDPE), 알루미늄, 철 등', '[밀크씨슬추출물]간 건강에 도움을 줄 수 있음', '1. 직사광선을 피해 서늘한 곳에 보관하시고, 어린이의 손이 닿지 않는 곳에 보관하십시오. 2. 제품 개봉 후에는 흡습이 일어날 수 있으니 반드시 밀봉하여 보관하십시오.', '알레르기 반응이 나타나는 경우에는 섭취 중단설사, 위통, 복부팽만 등의 위장관계 장애가 나타나는 경우에는 섭취에 주의', 10, '밀크씨슬', '자주 먹는 영양제 (대표 제품)'),
  ('20172880193358', 39109, '유한 밀크씨슬', '유한 밀크씨슬', '대원헬스케어 주식회사 2공장', '간', '2025-10-13'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 연한 황갈색의 장방형 제피 정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는 폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE)/PTP포장 - 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[밀크씨슬추출물] 간 건강에 도움을 줄 수 있음[비타민B1] 탄수화물과 에너지 대사에 필요 [비타민B2] 체내 에너지 생성에 필요[비타민B6] 단백질 및 아미노산 이용에 필요 / 혈액의 호모시스테인 수준을 정상으로 유지하는데 필요[비타민E] 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[셀렌] 유해산소로부터 세포를 보호하는데 필요[아연] 정상적인 면역기능에 필요 / 정상적인 세포분열에 필요', '직사광선을 피하여 실온에 보관하시고, 영ᆞ유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[밀크씨슬추출물]어린이, 임산부 및 수유부는 섭취를 피할 것알레르기 반응이 나타나는 경우에는 섭취 중단설사, 위통, 복부팽만 등의 위장관계 장애가 나타나는 경우에는 섭취에 주의이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B1]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B2]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B6]손발 따끔거림, 작열감 또는 저림 등의 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 18, '밀크씨슬', '자주 먹는 영양제'),
  ('20120017002152', 12277, '일양 간건강 밀크씨슬', '일양 간건강 밀크씨슬', '이앤에스(주)', '간', '2020-03-25'::date, '24개월', '고유의 향미가 있고 이미, 이취가 없으며 광택이 없는 연한 황갈색의 장방형 코팅 정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', 'PVC, 알루미늄호일', '① 간 건강에 도움을 줄 수 있음①체내 에너지 생성에 필요①정상적인 면역기능에 필요②정상적인 세포분열에 필요①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①탄수화물과 에너지 대사에 필요①체내 에너지 생성에 필요', '직사광선 및 고온다습한 곳을 피하여 서늘한 실온에 보관하십시오.', '1) 소비기한을 확인하시기 바라며, 섭취량 및 섭취방법을 준수하시기 바랍니다.2) 알레르기 반응이 나타나는 경우에는 섭취를 중단하십시오.3) 설사, 위통, 복부팽만 등의 위장관계 장애가 나타나는 경우에는 섭취에 주의하십시오.4) 어린이, 임산부 및 수유부는 섭취를 피하십시오.5) 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.', 21, '밀크씨슬', '자주 먹는 영양제'),
  ('20040015094261', 40293, '광동 홍삼진스틱', '광동 홍삼진스틱', '(주)화인내츄럴', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2025-12-16'::date, '제조일로부터 36개월', '고유의 향미가 있고, 이미 · 이취가 없는 진한 갈색의 액상', '1일 1회, 1회 1포(10g) 씩 섭취하십시오.', 'PE(폴리에틸렌) 또는 PP(폴리프로필렌)', '(1)기능성 내용 : 면역력 증진･피로개선･혈소판 응집억제를 통한 혈액흐름･기억력 개선･항산화에 도움을 줄 수 있음(2) 일일섭취량 (가)면역력 증진･피로개선에 도움을 줄 수 있음 : 진세노사이드 Rg1, Rb1 및 Rg3의 합계로서 3~80 mg (나)혈소판 응집억제를 통한 혈액흐름･기억력 개선･항산화에 도움을 줄 수 있음 : 진세노사이드 Rg1, Rb1 및 Rg3의 합계로서 2.4~80 mg', '습기와 직사광선을 피하여 서늘한 곳에 보관하십시오. (실온보관, 실온유통)', '(3) 섭취 시 주의사항 (가)당뇨치료제 및 혈액항응고제 복용 시 섭취에 주의 (나)알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음 (다)이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것,(3) 섭취 시 주의사항 (가)당뇨치료제 및 혈액항응고제 복용 시 섭취에 주의 (나)알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음 (다)이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 8, '홍삼', '자주 먹는 영양제'),
  ('20040016036165', 43174, '유한데일리홍삼', '유한데일리홍삼', '(주)천호엔케어', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2026-05-18'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 갈색의 액상', '1일 1회, 1회 1포를 섭취하십시오.', '폴리에틸렌(PE)', '홍삼: 면역력 증진･피로개선･혈소판 응집억제를 통한 혈액흐름･기억력 개선･항산화에 도움을 줄 수 있음', '실온보관(직사광선 피해 서늘한 곳에 보관)', '(1)당뇨치료제 및 혈액항응고제 복용 시 섭취에 주의 (2)알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있음 (3)이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 21, '홍삼', '자주 먹는 영양제'),
  ('20040017015126', 4153, '일동후디스 純(순)홍삼 으뜸아이', '일동후디스 純(순)홍삼 으뜸아이', '(주)휴온스엔', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2014-12-03'::date, '제조일로부터 24개월까지', '갈색~진한 갈색의 액상', '1일 1회, 1회 1포(20ml)씩 섭취하십시오.', '폴리프로필렌', '[홍삼제품]①면역력 증진에 도움을 줄 수 있음②피로개선에 도움을 줄 수 있음③혈소판 응집 억제를 통한 혈액흐름에 도움을 줄 수 있음④기억력 개선에 도움을 줄 수 있음⑤항산화에 도움을 줄 수 있음', '직사광선을 피하고 서늘한 곳에 보관하시고, 개봉 후에는 가급적 빨리 섭취하십시오.', '[홍삼제품]의약품(당뇨치료제, 혈액항응고제) 복용 시 섭취에 주의
1) 특이체질, 알레르기 체질인 경우 구입처 및 소비자상담실에 문의하신 후 섭취하시기 바랍니다.
2) 제품의 특성 상 침전물이 생길 수 있으므로 잘 흔들어 드십시오.
3) 전자레인지에 직접 데우지 마십시오.
4) 개봉 시 내용물이 흘러 나올 수 있으므로 주의하십시오.
5) 포장이 변형, 팽창, 손상되었거나 내용물이 변질되었을 경우 음용하지 마십시오.
6) 개봉부 및 가장자리에 다치치 않도록 주의하십시오.', 21, '홍삼', '자주 먹는 영양제'),
  ('2004001706891', 1226, '일양6년근발효홍삼정', '일양6년근발효홍삼정', '일양약품(주)', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2010-07-09'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미·이취가 없는 진한 갈색의 액상', '1일2회, 1회(1g)을 그대로 섭취하거나 음료수 또는 물(25ml정도)에 타서 섭취하십시오.', '폴리에틸렌, 유리병', '[홍삼제품] 면역력 증진·피로개선·혈소판 응집억제를 통한 혈액흐름·기억력 개선·항산화에 도움을 줄 수 있음', '직사광선을 받지 아니하는 서늘한 곳에서 보관 및 유통하십시오.', '의약품(당뇨치료제, 혈액항응고제) 복용 시 섭취에 주의', 1, '홍삼', '자주 먹는 영양제'),
  ('20040020036169', 31909, '정관장 홍삼정', '정관장 홍삼정', '(주)다정', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2024-07-01'::date, '제조일로부터 36개월', '고유의 향미가 있고 이미, 이취가 없는 흑갈색의 점성을 갖는 액상', '1일 1회, 1회 3g을 온수 또는 냉수에 타거나 직접 섭취하십시오.', '용기(유리)/뚜껑(폴리에틸렌)', '①면역력 증진에 도움을 줄 수 있음②피로개선에 도움을 줄 수 있음③혈소판 응집 억제를 통한 혈액흐름에 도움을 줄 수 있음④기억력 개선에 도움을 줄 수 있음⑤항산화에 도움을 줄 수 있음', '직사광선을 피하여 실온에 보관하십시오. 개봉 후에는 속마개는 버리시고 뚜껑을 닫아 반드시 냉장(0~10℃) 보관하십시오.', '- 특이체질 및 알레르기 체질의 경우 성분을 확인하신 후 섭취하십시오- 당뇨치료제 및 혈액항응고제 복용 시 섭취에 주의하십시오- 알레르기 체질 등은 개인에 따라 과민반응을 나타낼 수 있습니다.- 이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오- 임산부, 수유기 여성 및 14세 이하 아동 섭취금지(중국)', 1, '홍삼', '자주 먹는 영양제'),
  ('20040020016611', 9094, '종근당건강 홍삼정K', '종근당건강 홍삼정K', '종근당건강(주)', '인지기능/기억력, 피로, 갱년기 여성, 혈행, 면역, 항산화', '2018-11-15'::date, '제조일로부터 24개월', '진갈색의 점성이 있는 액상으로 이미, 이취가 없고 고유의 향미를 가짐.', '1일1회 1회 3g을 그냥 드시거나 기호에 따라 냉수 또는 온수에 타서 드십시오.', '유리, 폴리에틸렌(HDPE)', '①면역력 증진에 도움을 줄 수 있음②피로개선에 도움을 줄 수 있음③혈소판 응집 억제를 통한 혈액흐름에 도움을 줄 수 있음④기억력 개선에 도움을 줄 수 있음⑤항산화에 도움을 줄 수 있음', '직사광선을 받지 않는 서늘한 곳에 보관하여야한다.', '의약품(당뇨치료제, 혈액항응고제) 복용 시 섭취에 주의특이체질 및 알러지 체질의 경우 성분을 확인하신 후 섭취하십시오.섭취량 및 섭취방법을 확인하시고 섭취하여 주십시오.제품 개봉 또는 섭취 시 포장재에 의해 다칠 우려가 있으니 주의하시기 바랍니다.임산부, 수유부, 만성질환이 있거나 현재 질병 치료중이신 분은 전문의와 상의 후 섭취하십시오.', 2, '홍삼', '자주 먹는 영양제'),
  ('200600200081386', 42094, '고려은단 코엔자임Q10', '고려은단 코엔자임Q10', '주식회사 노바렉스2공장', '혈압, 항산화', '2026-03-25'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미·이취가 없는 주황의 점도가 있는 내용물을 함유한 빨강의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '폴리에틸렌테레프탈레이트(PET), 폴리에틸렌(PE), 고밀도폴리에틸렌(HDPE), 저밀도폴리에틸렌(LDPE), 폴리프로필렌(PP), 폴리스틸렌(PS), 폴리염화비닐리덴(PVDC), 폴리염화비닐/알루미늄호일, 알루미늄(AL)', '[코엔자임Q10] 항산화·높은 혈압 감소에 도움을 줄 수 있음
