  ('20040020046441', 3896, '광동 코큐텐플러스', '광동 코큐텐플러스', '한국바이오팜(주)에이치피', '혈압, 항산화', '2014-08-06'::date, '24개월', '적갈색 연질캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취한다.', 'PVC(폴리염화비닐)/Aluminium Foil(알루미늄 호일), 폴리에틸렌테레프탈레이트(PET), 폴리에틸렌(PE)', '[코엔자임Q10제품]①항산화에 도움을 줄 수 있음② 높은 혈압 감소에 도움을 줄 수 있음
[비타민E]①유해산소로부터 세포를 보호하는데 필요', '직사광선을 받지 않는 실온에 보관합니다.', '1) 알레르기, 특이체질이신 경우 성분을 확인하신 후 섭취하여 주시기 바랍니다.
