  ('200700170352026', 19438, '솔가 코큐텐 100MG', '솔가 코큐텐 100MG', '코스맥스엔비티(주)', '혈압, 항산화', '2022-01-25'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 노란 주황의 내용물을 함유한 갈흑색의 타원형 연질 캡슐', '1일 1회, 1회 1캡슐을 물과 함께 섭취하십시오.', '유리 / 캡 : 폴리프로필렌(PP), 저밀도폴리에틸렌(LDPE), 외캡-알루미늄, 내캡-PP(폴리프로필렌) / PE(폴리에틸렌), 실링지-EVA, 폴리에틸렌(PE), 폴리스틸렌(PS), 고밀도폴리에틸렌(HDPE), 폴리에틸렌테레프탈레이트(PET), 폴리프로필렌(PP), 저밀도폴리에틸렌(LDPE)', '[코엔자임Q10] 항산화･높은 혈압 감소에 도움을 줄 수 있음', '실온/ 1. 직사광선을 피해 서늘한 곳에 보관하시고, 어린이의 손이 닿지 않는 곳에 보관하십시오.2. 제품 개봉 후에는 흡습이 일어날 수 있으니 반드시 밀봉하여 보관하십시오.', '1. 이상사례 발생 시 섭취를 중단하고 전문가와 상담하시기 바랍니다.2. 유통기한을 확인 후 섭취하시기 바라며, 섭취량 및 섭취방법을 준수하시기 바랍니다.', 11, '코엔자임Q10', '자주 먹는 영양제 (대표 제품)'),
  ('200400200024021', 41373, '유한 나토 코큐텐', '유한 나토 코큐텐', '코스맥스바이오(주)', '혈압, 항산화', '2026-02-09'::date, '제조일로부터 2년', '고유의 향미가 있고 이미, 이취가 없는 노란 주황색의 내용물을 함유한 어두운 갈색의 타원형 연질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', 'PTP(폴리염화비닐+알루미늄호일), PTP(폴리염화비닐리덴+알루미늄호일)', '1) 나토균배양분말 : 혈행 개선에 도움을 줄 수 있음.2) 코엔자임Q10 : 항산화·높은 혈압 감소에 도움을 줄 수 있음.3) 비타민C : 결합조직 형성과 기능유지에 필요, 철의 흡수에 필요, 항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요.4) 아연 : 정상적인 면역기능에 필요, 정상적인 세포분열에 필요.', '수분 및 열에 의해 영향을 받을 수 있으므로 직사광선을 피해 서늘한 곳에 보관하십시오. 어린이 손에 닿지 않는 곳에 보관하십시오.', '섭취 시 목에 걸릴 수 있으므로 반드시 물과 함께 섭취하십시오. 섭취 시 위장장애, 소화불량의 증상이 있을 경우 섭취를 중단하십시오.개인의 신체 상태에 따라 이상 증상이 생길 경우 섭취를 중단하십시오.섭취 전 제품에 이상이 있는 경우 섭취를 금하십시오.특정 원료 성분에 알레르기 체질은 원료 성분을 확인 후 섭취하십시오.대두에 알레르기를 나타내는 사람은 섭취에 주의하십시오.어린이, 임산부 및 수유부는 섭취를 피하십시오.수술전후, 의약품(항응고제) 복용 시 전문가와 상담하십시오.이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.수유부는 섭취를 피하십시오.항응고제 복용 시 전문가와 상담하십시오.과량 섭취하지 않도록 주의하십시오.신장질환이 있는 경우 섭취 전 전문가와 상담하십시오.', 13, '코엔자임Q10', '자주 먹는 영양제'),
  ('200400150831819', 23859, '광동 혈행&기억력 징코', '광동 혈행&기억력 징코', '주식회사한미양행', '인지기능/기억력, 혈행', '2023-01-26'::date, '제조일로부터 24개월까지', '고유의 향미를 지니고 이미, 이취가 없는 흐린 황갈색 또는 회황색의 장방형 제피정제.', '1일 1회, 1회 1정을 충분한 물과 함께 섭취하십시오.', '병포장:폴리에틸렌(PE),폴리에틸렌테레프탈레이트(PET),폴리스티렌(PS)/PTP포장:폴리염화비닐(PVC)+알루미늄호일(AL-FOIL) 등', '-기억력 개선·혈행 개선에 도움을 줄 수 있음(1) 탄수화물과 에너지 대사에 필요(1) 체내 에너지 생성에 필요①단백질 및 아미노산 이용에 필요②혈액의 호모시스테인 수준을 정상으로 유지하는데 필요①정상적인 면역기능에 필요②정상적인 세포분열에 필요①유해산소로부터 세포를 보호하는데 필요', '고온다습한 곳이나 직사광선을 피하여 서늘한 곳에 보관.', '알레르기 체질이신 경우 성분을 확인 한 후 섭취하시기 바랍니다.[은행잎 추출물](가) 임산부, 수유부, 어린이 및 수술전후 환자는 섭취에 주의(나) 의약품(항응고제) 복용 시 섭취에 주의[비타민B1]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민B2]이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 28, '은행잎', '시나리오: 와파린·항혈소판제와 출혈 주의'),
  ('20220011370119', 29596, '유한m 징코미네랄플러스', '유한m 징코미네랄플러스', '동서바이오팜(주) 안성공장', '인지기능/기억력, 혈행', '2024-02-15'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미, 이취가 없는 회황색의 장방형 제피정제', '1일 1회, 1회 2정을 충분한 물과 함께 섭취하십시오.', '폴리에틸렌(PE), 폴리프로필렌(PP), 폴리에틸렌테레프탈레이트(PET), 폴리스틸렌(PS), 폴리염화비닐(PVC), 알루미늄호일(Al-Foil) 등', '[은행잎추출물]기억력 개선·혈행 개선에 도움을 줄 수 있음[철]체내 산소운반과 혈액생성에 필요②에너지 생성에 필요[망간]①뼈 형성에 필요②에너지 이용에 필요③유해산소로부터 세포를 보호하는데 필요[아연]①정상적인 면역기능에 필요②정상적인 세포분열에 필요[셀레늄]유해산소로부터 세포를 보호하는데 필요[구리]①철의 운반과 이용에 필요②유해산소로부터 세포를 보호하는데 필요', '고온다습, 직사광선을 피하여 건조하고 서늘한 곳에서 보관 및 유통하십시오. 영·유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '임산부, 수유부, 어린이 및 수술전후 환자는 섭취에 주의의약품(항응고제) 복용 시 섭취에 주의특히 6세 이하는 과량섭취하지 않도록 주의', 22, '은행잎', '시나리오: 와파린·항혈소판제와 출혈 주의'),
  ('200700170352916', 36383, '일동 브레인 피에스 징코', '일동 브레인 피에스 징코', '코스맥스엔비티(주)', '인지기능/기억력, 혈행', '2025-05-01'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 녹갈색의 점도가 있는 내용물을 함유한 검정색의 장방형 연질캡슐', '1일 1회, 1회 2캡슐을 물과 함께 섭취하십시오.', 'PVC, Al-foil', '[비타민 E]항산화 작용을 하여 유해산소로부터 세포를 보호하는데 필요[은행잎 추출물]기억력 개선･혈행 개선에 도움을 줄 수 있음[포스파티딜세린]노화로 인해 저하된 인지력 개선 ･ 자외선에 의한 피부 손상으로부터 피부 건강 유지 ･ 피부보습에 도움을 줄 수 있음', '실온보관 / 1)직사광선이나 고온다습한 곳을 피하여 청결하고 서늘한 곳에 보관하십시오. 2)영,유아 및 어린이의 손이 닿지 않는 곳에 보관하십시오.', '[은행잎 추출물]임산부, 수유부, 어린이 및 수술전후 환자는 섭취에 주의의약품(항응고제) 복용 시 섭취에 주의[포스파티딜세린]임산부와 수유부는 섭취에 주의과잉섭취 시 위장장애나 불면증을 유발할 수 있음', 10, '은행잎', '시나리오: 와파린·항혈소판제와 출혈 주의'),
  ('200400200141940', 34936, '광동명품비타민K2프리미엄', '광동명품비타민K2프리미엄', '광동헬스바이오(주) 2공장', null, '2025-01-22'::date, '제조일부터 24개월', '고유의 향미가 있고 이미, 이취가 없으며 점박이가 있는 흰색의 장방형 제피정제', '1일 1회, 1회 1정을 물과 함께 섭취하십시오.', '병포장 - 폴리에틸렌(PE) 또는 폴리에틸렌테레프탈레이트(PET) 또는 폴리스틸렌(PS) 또는 폴리프로필렌(PP) 또는 고밀도폴리에틸렌(HDPE) 또는 저밀도폴리에틸렌(LDPE)/PTP포장 - 염화비닐수지(PVC) + 알루미늄호일(Al-Foil) 또는 염화비닐리덴수지(PVDC) + 알루미늄호일(Al-Foil)', '[비타민K]1. 정상적인 혈액응고에 필요2. 뼈의 구성에 필요[비타민D]1. 칼슘과 인이 흡수되고 이용되는데 필요2. 뼈의 형성과 유지에 필요3. 골다공증발생 위험 감소에 도움을 줌', '직사광선을 피하고 서늘한 곳에 보관 및 유통(실온)', '[비타민K]1. 항응고제 등 복용 시 전문가와 상담할 것2. 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것[비타민D]3. 고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것4. 이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 10, '비타민K', '시나리오: 와파린과 부딪힘'),
  ('200400200073434', 45066, '여에스더 비타민K2 플러스 D3', '여에스더 비타민K2 플러스 D3', '(주)한국씨엔에스팜', null, '2026-08-26'::date, '제조일로부터 24개월까지', '고유의 향미가 있고 이미·이취가 없는 밝은 회황색의 내용물을 함유한 투명한 경질캡슐', '1일 1회, 1회 1캡슐을 충분한 물과 함께 섭취하십시오.', '병포장(HDPE, PET, PE, PP), PTP포장(PVC, PVDC, AL-foil)', '[비타민 D] 칼슘과 인이 흡수되고 이용되는데 필요, 뼈의 형성과 유지에 필요, 골다공증발생 위험 감소에 도움을 줌[비타민 K] 정상적인 혈액응고에 필요, 뼈의 구성에 필요', '직사광선을 받지 아니하는 서늘한 곳에서 보관 및 유통하시고, 어린이의 손에 닿지 않도록 주의하시기 바랍니다.', '.고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담할 것.항응고제 등 복용 시 전문가와 상담할 것.이상사례 발생 시 섭취를 중단하고 전문가와 상담할 것', 21, '비타민K', '시나리오: 와파린과 부딪힘'),
  ('20140020012199', 35024, '유한m 칼슘 마그네슘 비타민 D 비타민 K2', '유한m 칼슘 마그네슘 비타민 D 비타민 K2', '(주)아오스', null, '2025-02-05'::date, '제조일로부터 24개월', '고유의 향미가 있고 이미, 이취가 없는 흰색의 장방형 제피정제', '1일 1회, 1회 2정을 충분한 물과 함께 섭취하십시오.', '폴리에틸렌(PE), 폴리에틸렌테레프탈레이트(PET), 폴리스틸렌(PS), 폴리프로필렌(PP), 염화비닐수지(PVC), 알루미늄호일(Al-Foil)', '[칼슘] : 뼈와 치아 형성에 필요, 신경과 근육 기능 유지에 필요, 정상적인 혈액응고에 필요, 골다공증발생 위험 감소에 도움을 줌[마그네슘] : 에너지 이용에 필요, 신경과 근육 기능 유지에 필요[비타민 D] : 칼슘과 인이 흡수되고 이용되는데 필요, 뼈의 형성과 유지에 필요, 골다공증발생 위험 감소에 도움을 줌[비타민 K] : 정상적인 혈액응고에 필요, 뼈의 구성에 필요', '습기와 직사광선을 피하여 서늘한 곳에 보관하십시오.제품 개봉 후에는 인습되지 않게 주의하여 보관하십시오.', '고칼슘혈증이 있거나 의약품 복용 시 전문가와 상담하십시오.항응고제 등 복용 시 전문가와 상담하십시오.이상사례 발생 시 섭취를 중단하고 전문가와 상담하십시오.특이체질 또는 알레르기 체질인 경우에는 개인에 따라 과민반응을 나타낼 수 있으므로 원재료를 확인한 후 섭취하십시오.', 10, '비타민K', '시나리오: 와파린과 부딪힘');

